import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext.jsx';
import authService from '../services/authService.jsx';

const Login = ({ onLogin }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [formData, setFormData] = useState({ 
    email: '', 
    password: '', 
    name: '', 
    role: 'farmer' 
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showCodeInput, setShowCodeInput] = useState(false);
  const [inspectorCode, setInspectorCode] = useState('');
  const navigate = useNavigate();
  const { t } = useLanguage();
  
  const INSPECTOR_CODE = 'INSPECTOR2024';

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');
    
    try {
      let result;
      if (isSignUp) {
        if (isSignUp && formData.role === 'inspector' && inspectorCode !== INSPECTOR_CODE) {
          setError('Invalid Inspector code. Please contact system admin.');
          setIsLoading(false);
          return;
        }
        result = await authService.signUp(formData.email, formData.password, {
          name: formData.name,
          role: formData.role
        });
      } else {
        result = await authService.signIn(formData.email, formData.password);
      }
      
      if (result.success) {
        onLogin(result.user);
        navigate('/');
      } else {
        setError(result.error || 'Authentication failed');
      }
    } catch (err) {
      setError('Authentication failed: ' + err.message);
    }
    setIsLoading(false);
  };


  return (
    <div className="container mt-5">
      <div className="row justify-content-center">
        <div className="col-md-6">
          <div className="card fade-in-up">
            <div className="card-header text-center">
              <i className="fas fa-sheep fa-3x mb-3"></i>
              <h3 className="fw-bold">{isSignUp ? 'Sign Up' : t('login')} to {t('woolMonitor')}</h3>
            </div>
            <div className="card-body p-5">
              {error && (
                <div className="alert alert-danger fade-in-up">
                  <i className="fas fa-exclamation-triangle me-2"></i>
                  {error}
                </div>
              )}
              
              <form onSubmit={handleSubmit}>
                {isSignUp && (
                  <div className="mb-4">
                    <label className="form-label fw-semibold">
                      <i className="fas fa-user me-2"></i>
                      Full Name
                    </label>
                    <input
                      type="text"
                      className="form-control"
                      value={formData.name}
                      onChange={(e) => setFormData({...formData, name: e.target.value})}
                      placeholder="Enter your full name"
                      required
                    />
                  </div>
                )}

                <div className="mb-4">
                  <label className="form-label fw-semibold">
                    <i className="fas fa-envelope me-2"></i>
                    Email
                  </label>
                  <input
                    type="email"
                    className="form-control"
                    value={formData.email}
                    onChange={(e) => setFormData({...formData, email: e.target.value})}
                    placeholder="Enter your email"
                    required
                  />
                </div>
                
                <div className="mb-4">
                  <label className="form-label fw-semibold">
                    <i className="fas fa-lock me-2"></i>
                    {t('password')}
                  </label>
                  <input
                    type="password"
                    className="form-control"
                    value={formData.password}
                    onChange={(e) => setFormData({...formData, password: e.target.value})}
                    placeholder={t('enterPassword')}
                    required
                  />
                </div>

                {isSignUp && (
                  <div className="mb-4">
                    <label className="form-label fw-semibold">
                      <i className="fas fa-user-tag me-2"></i>
                      Role
                    </label>
                    <select
                      className="form-select"
                      value={formData.role}
                      onChange={(e) => {
                        setFormData({...formData, role: e.target.value});
                        setShowCodeInput(e.target.value === 'inspector');
                      }} required
                    >
                      <option value="farmer">Farmer/Retailer</option>
                      <option value="buyer">Buyer</option>
                      <option value="government">Government Admin</option>
                      <option value="inspector">Inspector</option>
                    </select>
                  </div>
                )}
                
                {showCodeInput && (
                  <div className="mb-4">
                    <label className="form-label fw-semibold">
                      <i className="fas fa-key me-2"></i>Inspector Access Code
                    </label>
                    <input
                      type="password"
                      className="form-control"
                      value={inspectorCode}
                      onChange={e => setInspectorCode(e.target.value)}
                      placeholder="Enter inspector code"
                      required
                    />
                  </div>
                )}
                
                <button type="submit" className="btn btn-primary w-100 mb-3" disabled={isLoading}>
                  {isLoading ? (
                    <>
                      <span className="spinner-border spinner-border-sm me-2" role="status"></span>
                      {isSignUp ? 'Creating Account...' : t('loggingIn')}
                    </>
                  ) : (
                    <>
                      <i className={`fas fa-${isSignUp ? 'user-plus' : 'sign-in-alt'} me-2`}></i>
                      {isSignUp ? 'Sign Up' : t('login')}
                    </>
                  )}
                </button>
              </form>

              <div className="text-center mb-3">
                <button 
                  className="btn btn-link"
                  onClick={() => setIsSignUp(!isSignUp)}
                >
                  {isSignUp ? 'Already have an account? Login' : 'Need an account? Sign Up'}
                </button>
              </div>
              
              <div className="mt-4">
                <div className="alert alert-info">
                  <h6 className="fw-bold mb-2">
                    <i className="fas fa-info-circle me-2"></i>
                    Create Account
                  </h6>
                  <p className="mb-0 small">
                    Sign up with your email and choose your role (Farmer, Buyer, Government, or Quality Assessor).
                    Your account will be created in Firebase and you can start using the system immediately.
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;