import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import firebaseService from '../services/firebaseService.jsx';
import AuthGuard from '../components/AuthGuard.jsx';
import { useLanguage } from '../context/LanguageContext.jsx';
import { useTheme } from '../context/ThemeContext.jsx';
import woolQualityService from '../services/woolQualityService.jsx';
import WoolQualityDetails from '../components/WoolQualityDetails.jsx';

const ProductCatalog = ({ user }) => {
  useLanguage(); // For language context
  useTheme(); // For theme context
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);
  const [filters, setFilters] = useState({
    search: '',
    category: '',
    minPrice: '',
    maxPrice: '',
    grade: ''
  });
  const [sortBy, setSortBy] = useState('newest');
  const [selectedProductId, setSelectedProductId] = useState(null);
  const [productQuality, setProductQuality] = useState({});

  useEffect(() => {
    loadProducts();
  }, []);

  const loadProducts = async () => {
    try {
      const batches = await firebaseService.getAllAvailableBatches();
      
      const products = batches.map(batch => ({
        id: batch.batchId,
        name: `Premium ${batch.woolType} Wool`,
        price: batch.price,
        image: '/api/placeholder/300/200',
        category: batch.woolType,
        grade: batch.qualityGrade || 'A',
        weight: batch.weight,
        seller: batch.farmerName,
        location: batch.location,
        inStock: batch.status !== 'SOLD',
        rating: (Math.random() * 2 + 3).toFixed(1),
        reviews: Math.floor(Math.random() * 100) + 10,
        trackingId: batch.batchId
      }));
      setProducts(products);
    } catch (error) {
      console.error('Error loading products:', error);
      setProducts([]);
    }
  };

  const addToCart = async (product) => {
    if (!user) {
      alert('Please log in to add items to cart');
      return;
    }
    
    const existingItem = cart.find(item => item.id === product.id);
    let newCart;
    if (existingItem) {
      newCart = cart.map(item =>
        item.id === product.id
          ? { ...item, quantity: item.quantity + 1 }
          : item
      );
    } else {
      newCart = [...cart, { ...product, quantity: 1 }];
    }
    
    setCart(newCart);
  };

  const handleShowQuality = async (product) => {
    if (!product.id) return;
    if (!productQuality[product.id]) {
      const records = await woolQualityService.getQualityRecordByBatch(product.id);
      setProductQuality((prev) => ({ ...prev, [product.id]: records[0] || null }));
    }
    setSelectedProductId(product.id);
  };

  const filteredProducts = products.filter(product => {
    return (
      (!filters.search || product.name.toLowerCase().includes(filters.search.toLowerCase())) &&
      (!filters.category || product.category === filters.category) &&
      (!filters.minPrice || product.price >= parseFloat(filters.minPrice)) &&
      (!filters.maxPrice || product.price <= parseFloat(filters.maxPrice)) &&
      (!filters.grade || product.grade === filters.grade) &&
      product.inStock
    );
  });

  const sortedProducts = [...filteredProducts].sort((a, b) => {
    switch (sortBy) {
      case 'price-low': return a.price - b.price;
      case 'price-high': return b.price - a.price;
      case 'rating': return b.rating - a.rating;
      default: return 0;
    }
  });

  return (
    <div className="container-fluid py-4">
      {/* Header */}
      <div className="row mb-4">
        <div className="col-12">
          <div className="d-flex justify-content-between align-items-center">
            <h2>Wool Products</h2>
            <div className="d-flex gap-3">
              <span className="badge bg-primary fs-6">{cart.length} items in cart</span>
              <Link to="/cart" className="btn btn-success">
                <i className="fas fa-shopping-cart me-2"></i>
                View Cart (${cart.reduce((sum, item) => sum + (item.price * item.quantity), 0).toFixed(2)})
              </Link>
            </div>
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="row mb-4">
        <div className="col-12">
          <div className="card">
            <div className="card-body">
              <div className="row g-3">
                <div className="col-md-3">
                  <input
                    type="text"
                    className="form-control"
                    placeholder="Search products..."
                    value={filters.search}
                    onChange={(e) => setFilters({...filters, search: e.target.value})}
                  />
                </div>
                <div className="col-md-2">
                  <select
                    className="form-select"
                    value={filters.category}
                    onChange={(e) => setFilters({...filters, category: e.target.value})}
                  >
                    <option value="">All Types</option>
                    <option value="Merino">Merino</option>
                    <option value="Romney">Romney</option>
                    <option value="Corriedale">Corriedale</option>
                  </select>
                </div>
                <div className="col-md-2">
                  <select
                    className="form-select"
                    value={filters.grade}
                    onChange={(e) => setFilters({...filters, grade: e.target.value})}
                  >
                    <option value="">All Grades</option>
                    <option value="A+">A+ Premium</option>
                    <option value="A">A Grade</option>
                    <option value="B">B Grade</option>
                  </select>
                </div>
                <div className="col-md-2">
                  <input
                    type="number"
                    className="form-control"
                    placeholder="Min Price"
                    value={filters.minPrice}
                    onChange={(e) => setFilters({...filters, minPrice: e.target.value})}
                  />
                </div>
                <div className="col-md-2">
                  <select
                    className="form-select"
                    value={sortBy}
                    onChange={(e) => setSortBy(e.target.value)}
                  >
                    <option value="newest">Newest</option>
                    <option value="price-low">Price: Low to High</option>
                    <option value="price-high">Price: High to Low</option>
                    <option value="rating">Highest Rated</option>
                  </select>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Products Grid */}
      <div className="row">
        {sortedProducts.map(product => (
          <div key={product.id} className="col-lg-3 col-md-4 col-sm-6 mb-4">
            <div className="card h-100 shadow-sm">
              <div className="position-relative">
                <div className="card-img-top bg-light d-flex align-items-center justify-content-center" style={{height: '200px'}}>
                  <i className="fas fa-image fa-3x text-muted"></i>
                </div>
                <span className={`position-absolute top-0 end-0 m-2 badge bg-${product.grade === 'A+' ? 'success' : 'primary'}`}>
                  {product.grade}
                </span>
              </div>
              
              <div className="card-body">
                <h6 className="card-title">{product.name}</h6>
                <p className="text-muted small mb-2">{product.seller} - {product.location}</p>
                
                <div className="d-flex justify-content-between align-items-center mb-2">
                  <span className="h5 text-success mb-0">${product.price}/kg</span>
                  <div className="text-end">
                    <i className="fas fa-star text-warning"></i>
                    <small>{product.rating} ({product.reviews})</small>
                  </div>
                </div>
                
                <p className="small text-muted">Available: {product.weight} kg</p>
                
                <AuthGuard user={user} action="add to cart">
                  <button
                    className="btn btn-primary w-100"
                    onClick={() => addToCart(product)}
                    disabled={!product.inStock}
                  >
                    <i className="fas fa-cart-plus me-2"></i>
                    {product.inStock ? 'Add to Cart' : 'Out of Stock'}
                  </button>
                </AuthGuard>
                <button className="btn btn-outline-info btn-sm w-100 mb-2" onClick={()=>handleShowQuality(product)}>
                  View Wool Quality
                </button>
                {selectedProductId === product.id &&
                  <WoolQualityDetails quality={productQuality[product.id]} />
                }
              </div>
            </div>
          </div>
        ))}
      </div>

      {sortedProducts.length === 0 && (
        <div className="text-center py-5">
          <i className="fas fa-search fa-3x text-muted mb-3"></i>
          <h5 className="text-muted">No products found</h5>
          <p className="text-muted">Try adjusting your filters</p>
        </div>
      )}
    </div>
  );
};

export default ProductCatalog;