import React from 'react';

const OrderTrackingSteps = ({ order, trackingHistory = [] }) => {
  const getStepStatus = (step) => {
    if (!order) return 'pending';
    
    switch (step) {
      case 'ORDER_PLACED':
        return 'completed';
      case 'PAYMENT_CONFIRMED':
        return order.paymentStatus === 'CONFIRMED' ? 'completed' : 'pending';
      case 'PROCESSING':
        return order.status === 'PROCESSING' || order.status === 'SHIPPED' || order.status === 'DELIVERED' ? 'completed' : 'pending';
      case 'SHIPPED':
        return order.status === 'SHIPPED' || order.status === 'DELIVERED' ? 'completed' : 'pending';
      case 'DELIVERED':
        return order.status === 'DELIVERED' ? 'completed' : 'pending';
      default:
        return 'pending';
    }
  };

  const getStepIcon = (step, status) => {
    if (status === 'completed') {
      return <i className="fas fa-check-circle text-success"></i>;
    } else if (status === 'active') {
      return <i className="fas fa-clock text-primary"></i>;
    } else {
      return <i className="fas fa-circle text-muted"></i>;
    }
  };

  const steps = [
    {
      key: 'ORDER_PLACED',
      title: 'Order Placed',
      description: 'Your order has been placed successfully',
      icon: 'fas fa-shopping-cart'
    },
    {
      key: 'PAYMENT_CONFIRMED',
      title: 'Payment Confirmed',
      description: 'Payment has been processed and confirmed',
      icon: 'fas fa-credit-card'
    },
    {
      key: 'PROCESSING',
      title: 'Processing',
      description: 'Your order is being prepared',
      icon: 'fas fa-cogs'
    },
    {
      key: 'SHIPPED',
      title: 'Shipped',
      description: 'Your order has been shipped',
      icon: 'fas fa-truck'
    },
    {
      key: 'DELIVERED',
      title: 'Delivered',
      description: 'Your order has been delivered',
      icon: 'fas fa-home'
    }
  ];

  return (
    <div className="order-tracking-steps">
      <div className="row">
        {steps.map((step, index) => {
          const status = getStepStatus(step.key);
          const isActive = status === 'completed' || (status === 'active');
          
          return (
            <div key={step.key} className="col-md-2 col-6 mb-3">
              <div className={`step-item text-center ${isActive ? 'active' : ''}`}>
                <div className="step-icon mb-2">
                  {getStepIcon(step.key, status)}
                </div>
                <div className="step-content">
                  <h6 className="step-title mb-1">{step.title}</h6>
                  <p className="step-description small text-muted mb-0">
                    {step.description}
                  </p>
                  {trackingHistory.find(entry => entry.status === step.key) && (
                    <small className="text-success">
                      {new Date(trackingHistory.find(entry => entry.status === step.key).timestamp).toLocaleDateString()}
                    </small>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>
      
      <style jsx>{`
        .step-item {
          padding: 15px 10px;
          border-radius: 8px;
          transition: all 0.3s ease;
          position: relative;
        }
        
        .step-item.active {
          background-color: #f8f9fa;
          border: 1px solid #dee2e6;
        }
        
        .step-icon {
          font-size: 1.5rem;
        }
        
        .step-title {
          font-size: 0.9rem;
          font-weight: 600;
          color: #495057;
        }
        
        .step-description {
          font-size: 0.75rem;
          line-height: 1.2;
        }
        
        .step-item.active .step-title {
          color: #007bff;
        }
        
        .step-item.active .step-description {
          color: #6c757d;
        }
        
        @media (max-width: 768px) {
          .step-item {
            padding: 10px 5px;
          }
          
          .step-title {
            font-size: 0.8rem;
          }
          
          .step-description {
            font-size: 0.7rem;
          }
        }
      `}</style>
    </div>
  );
};

export default OrderTrackingSteps;