import React, { useState, useEffect } from 'react';
import { useLanguage } from '../context/LanguageContext.jsx';
import firebaseService from '../services/firebaseService.jsx';

const UserProfile = ({ user }) => {
  const { t } = useLanguage();
  const [profile, setProfile] = useState({
    name: user?.name || '',
    email: user?.email || '',
    phone: '',
    address: '',
    farmName: '',
    farmSize: '',
    woolTypes: [],
    businessLicense: '',
    experience: '',
    specialization: ''
  });
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => {
    loadUserProfile();
  }, [user]);

  const loadUserProfile = async () => {
    if (!user?.uid) return;
    
    try {
      const userProfile = await firebaseService.getUserProfile(user.uid);
      if (userProfile) {
        setProfile(prev => ({ ...prev, ...userProfile }));
      }
    } catch (error) {
      console.error('Error loading profile:', error);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      await firebaseService.updateUserProfile(user.uid, profile);
      setMessage('Profile updated successfully!');
    } catch (error) {
      console.error('Error updating profile:', error);
      setMessage('Error updating profile. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfile(prev => ({ ...prev, [name]: value }));
  };

  return (
    <div className="container mt-4">
      <div className="row justify-content-center">
        <div className="col-md-8">
          <div className="card modern-card">
            <div className="card-header">
              <h3><i className="fas fa-user-edit me-2"></i>User Profile</h3>
              <p className="mb-0">Role: <span className="badge bg-primary">{user?.role}</span></p>
            </div>
            <div className="card-body">
              {message && (
                <div className={`alert ${message.includes('Error') ? 'alert-danger' : 'alert-success'}`}>
                  {message}
                </div>
              )}

              <form onSubmit={handleSubmit}>
                <div className="row">
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Name *</label>
                    <input
                      type="text"
                      className="form-control"
                      name="name"
                      value={profile.name}
                      onChange={handleChange}
                      required
                    />
                  </div>
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Email *</label>
                    <input
                      type="email"
                      className="form-control"
                      name="email"
                      value={profile.email}
                      onChange={handleChange}
                      required
                    />
                  </div>
                </div>

                <div className="row">
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Phone</label>
                    <input
                      type="tel"
                      className="form-control"
                      name="phone"
                      value={profile.phone}
                      onChange={handleChange}
                    />
                  </div>
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Address</label>
                    <input
                      type="text"
                      className="form-control"
                      name="address"
                      value={profile.address}
                      onChange={handleChange}
                    />
                  </div>
                </div>

                {user?.role === 'farmer' && (
                  <>
                    <div className="row">
                      <div className="col-md-6 mb-3">
                        <label className="form-label">Farm Name</label>
                        <input
                          type="text"
                          className="form-control"
                          name="farmName"
                          value={profile.farmName}
                          onChange={handleChange}
                        />
                      </div>
                      <div className="col-md-6 mb-3">
                        <label className="form-label">Farm Size (acres)</label>
                        <input
                          type="number"
                          className="form-control"
                          name="farmSize"
                          value={profile.farmSize}
                          onChange={handleChange}
                        />
                      </div>
                    </div>
                    <div className="mb-3">
                      <label className="form-label">Wool Types Produced</label>
                      <input
                        type="text"
                        className="form-control"
                        name="woolTypes"
                        value={profile.woolTypes}
                        onChange={handleChange}
                        placeholder="e.g., Merino, Corriedale, Romney"
                      />
                    </div>
                  </>
                )}

                {user?.role === 'buyer' && (
                  <div className="mb-3">
                    <label className="form-label">Business License</label>
                    <input
                      type="text"
                      className="form-control"
                      name="businessLicense"
                      value={profile.businessLicense}
                      onChange={handleChange}
                    />
                  </div>
                )}

                {user?.role === 'assessor' && (
                  <>
                    <div className="mb-3">
                      <label className="form-label">Years of Experience</label>
                      <input
                        type="number"
                        className="form-control"
                        name="experience"
                        value={profile.experience}
                        onChange={handleChange}
                      />
                    </div>
                    <div className="mb-3">
                      <label className="form-label">Specialization</label>
                      <input
                        type="text"
                        className="form-control"
                        name="specialization"
                        value={profile.specialization}
                        onChange={handleChange}
                        placeholder="e.g., Wool Quality Assessment, Fiber Analysis"
                      />
                    </div>
                  </>
                )}

                <div className="text-center">
                  <button 
                    type="submit" 
                    className="btn btn-primary btn-lg"
                    disabled={loading}
                  >
                    {loading ? (
                      <>
                        <span className="spinner-border spinner-border-sm me-2"></span>
                        Updating...
                      </>
                    ) : (
                      <>
                        <i className="fas fa-save me-2"></i>
                        Update Profile
                      </>
                    )}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default UserProfile;