import React, { useState, useEffect } from 'react';
import firebaseService from '../services/firebaseService.jsx';
import { MapContainer, TileLayer, Marker, Polyline, Popup, useMap } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';

// Fix for default markers
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
});

const BatchTrackingMap = ({ batchId, onClose }) => {
  const [trackingData, setTrackingData] = useState([]);
  const [batchInfo, setBatchInfo] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedEntry, setSelectedEntry] = useState(null);

  useEffect(() => {
    if (batchId) {
      loadTrackingData();
      loadBatchInfo();
    }
  }, [batchId]);

  const loadTrackingData = async () => {
    try {
      const data = await firebaseService.getBatchTrackingHistory(batchId);
      setTrackingData(data || []);
    } catch (error) {
      console.error('Error loading tracking data:', error);
    }
  };

  const loadBatchInfo = async () => {
    try {
      const batch = await firebaseService.getBatchById(batchId);
      setBatchInfo(batch);
    } catch (error) {
      console.error('Error loading batch info:', error);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status) => {
    const colors = {
      'CREATED': 'success',
      'IN_TRANSIT': 'warning',
      'IN_PROCESSING': 'info',
      'IN_STORAGE': 'primary',
      'DELIVERED': 'success',
      'COMPLETED': 'success'
    };
    return colors[status] || 'secondary';
  };

  const getProcessIcon = (process) => {
    const icons = {
      'movement': 'fas fa-truck',
      'processing': 'fas fa-cogs',
      'storage': 'fas fa-warehouse',
      'quality_check': 'fas fa-check-circle',
      'packaging': 'fas fa-box',
      'delivery': 'fas fa-shipping-fast'
    };
    return icons[process] || 'fas fa-circle';
  };

  const formatCoordinates = (coordinates) => {
    if (typeof coordinates === 'string') {
      return coordinates;
    }
    if (coordinates && coordinates.lat && coordinates.lng) {
      return `${coordinates.lat.toFixed(4)}, ${coordinates.lng.toFixed(4)}`;
    }
    return 'Unknown';
  };

  if (loading) {
    return (
      <div className="modal show d-block" style={{backgroundColor: 'rgba(0,0,0,0.8)'}}>
        <div className="modal-dialog modal-xl">
          <div className="modal-content">
            <div className="modal-body text-center py-5">
              <div className="spinner-border text-primary" role="status">
                <span className="visually-hidden">Loading...</span>
              </div>
              <p className="mt-3">Loading tracking data...</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Get coordinates array
  const validPoints = (trackingData || []).filter(entry => entry.location && entry.location.lat && entry.location.lng);
  const mapCenter = validPoints.length ? [validPoints[0].location.lat, validPoints[0].location.lng] : [20, 78];
  const pathCoordinates = validPoints.map(entry => [entry.location.lat, entry.location.lng]);

  function MapFlyTo({center}) {
    const map = useMap();
    useEffect(() => { map.setView(center, 8); }, [center, map]);
    return null;
  }

  return (
    <div className="modal show d-block" style={{backgroundColor: 'rgba(0,0,0,0.8)'}}>
      <div className="modal-dialog modal-xl">
        <div className="modal-content">
          <div className="modal-header bg-info text-white">
            <h5 className="modal-title">
              <i className="fas fa-map-marked-alt me-2"></i>
              Batch Tracking Map - {batchId}
            </h5>
            <button className="btn-close btn-close-white" onClick={onClose}></button>
          </div>
          <div className="modal-body">
            {/* Batch Info */}
            {batchInfo && (
              <div className="row mb-4">
                <div className="col-12">
                  <div className="card bg-light">
                    <div className="card-body">
                      <div className="row">
                        <div className="col-md-3">
                          <strong>Batch ID:</strong><br />
                          {batchInfo.batchId}
                        </div>
                        <div className="col-md-3">
                          <strong>Wool Type:</strong><br />
                          {batchInfo.woolType || 'N/A'}
                        </div>
                        <div className="col-md-3">
                          <strong>Weight:</strong><br />
                          {batchInfo.weight || 'N/A'} kg
                        </div>
                        <div className="col-md-3">
                          <strong>Status:</strong><br />
                          <span className={`badge bg-${getStatusColor(batchInfo.status)}`}>
                            {batchInfo.status || 'UNKNOWN'}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            <div className="row">
              {/* Tracking Timeline */}
              <div className="col-md-6">
                <div className="card">
                  <div className="card-header">
                    <h6 className="mb-0">
                      <i className="fas fa-history me-2"></i>
                      Tracking Timeline
                    </h6>
                  </div>
                  <div className="card-body" style={{maxHeight: '500px', overflowY: 'auto'}}>
                    {trackingData.length === 0 ? (
                      <div className="text-center py-4">
                        <i className="fas fa-inbox fa-3x text-muted mb-3"></i>
                        <p className="text-muted">No tracking data available</p>
                      </div>
                    ) : (
                      <div className="timeline">
                        {trackingData.map((entry, index) => (
                          <div 
                            key={entry.id || index}
                            className={`timeline-item ${selectedEntry?.id === entry.id ? 'active' : ''}`}
                            onClick={() => setSelectedEntry(entry)}
                            style={{cursor: 'pointer'}}>
                            <div className="timeline-marker">
                              <i className={getProcessIcon(entry.process)}></i>
                            </div>
                            <div className="timeline-content">
                              <div className="card">
                                <div className="card-body p-3">
                                  <div className="d-flex justify-content-between align-items-start mb-2">
                                    <h6 className="card-title mb-0">
                                      {entry.process ? entry.process.replace('_', ' ').toUpperCase() : 'MOVEMENT'}
                                    </h6>
                                    <small className="text-muted">
                                      {new Date(entry.timestamp).toLocaleString()}
                                    </small>
                                  </div>
                                  <p className="card-text small mb-2">
                                    <strong>Actor:</strong> {entry.actor || 'Unknown'}<br />
                                    <strong>Location:</strong> {formatCoordinates(entry.location)}<br />
                                    {entry.notes && (<><strong>Notes:</strong> {entry.notes}</>)}
                                  </p>
                                  <div className="d-flex gap-2">
                                    <span className={`badge bg-${getStatusColor(entry.status)}`}>
                                      {entry.status || 'ACTIVE'}
                                    </span>
                                    <span className="badge bg-secondary">
                                      #{index + 1}
                                    </span>
                                  </div>
                                </div>
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              </div>
              {/* Map Visualization */}
              <div className="col-md-6">
                <div className="card">
                  <div className="card-header">
                    <h6 className="mb-0">
                      <i className="fas fa-map me-2"></i>
                      Location Map
                    </h6>
                  </div>
                  <div className="card-body">
                    <div className="map-container" style={{height: '400px', backgroundColor: '#f8f9fa', borderRadius: '8px', position: 'relative'}}>
                      <MapContainer 
                        center={mapCenter} 
                        zoom={8} 
                        style={{ height: '100%', width: '100%' }}>
                        <MapFlyTo center={mapCenter} />
                        <TileLayer
                          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                        />
                        {validPoints.map((entry, idx) => (
                          <Marker
                            key={entry.id || idx}
                            position={[entry.location.lat, entry.location.lng]}
                          >
                            <Popup>
                              {entry.location && (
                                <div>
                                  <strong>{entry.process}</strong><br/>
                                  Lat: {entry.location.lat}, Lng: {entry.location.lng}<br/>
                                  {entry.notes && <span><strong>Notes:</strong> {entry.notes}</span>}
                                </div>
                              )}
                            </Popup>
                          </Marker>
                        ))}
                        {pathCoordinates.length > 1 && (
                          <Polyline positions={pathCoordinates} color="#007bff" weight={3} opacity={0.8} />
                        )}
                      </MapContainer>
                    </div>
                    {selectedEntry && (
                      <div className="mt-3 p-3 bg-light rounded">
                        <h6>Selected Entry:</h6>
                        <p className="mb-1">
                          <strong>Process:</strong> {selectedEntry.process}
                        </p>
                        <p className="mb-1">
                          <strong>Location:</strong> {formatCoordinates(selectedEntry.location)}
                        </p>
                        <p className="mb-1">
                          <strong>Actor:</strong> {selectedEntry.actor}
                        </p>
                        <p className="mb-0">
                          <strong>Time:</strong> {new Date(selectedEntry.timestamp).toLocaleString()}
                        </p>
                      </div>
                    )}
                  </div>
                </div>

                {/* Statistics */}
                <div className="card mt-3">
                  <div className="card-header">
                    <h6 className="mb-0">
                      <i className="fas fa-chart-bar me-2"></i>
                      Tracking Statistics
                    </h6>
                  </div>
                  <div className="card-body">
                    <div className="row text-center">
                      <div className="col-4">
                        <div className="border-end">
                          <h4 className="text-primary">{trackingData.length}</h4>
                          <small className="text-muted">Total Scans</small>
                        </div>
                      </div>
                      <div className="col-4">
                        <div className="border-end">
                          <h4 className="text-success">
                            {trackingData.filter(e => e.status === 'COMPLETED').length}
                          </h4>
                          <small className="text-muted">Completed</small>
                        </div>
                      </div>
                      <div className="col-4">
                        <h4 className="text-warning">
                          {trackingData.filter(e => e.status === 'IN_PROGRESS').length}
                        </h4>
                        <small className="text-muted">In Progress</small>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="modal-footer">
            <button className="btn btn-secondary" onClick={onClose}>
              Close
            </button>
            <button 
              className="btn btn-primary"
              onClick={() => window.print()}
            >
              <i className="fas fa-print me-2"></i>Print Report
            </button>
          </div>
        </div>
      </div>

      <style>{`
      .timeline {
        position: relative;
        padding-left: 30px;
      }
      .timeline-item { position: relative; margin-bottom: 20px; }
      .timeline-item::before {
        content: ''; position: absolute; left: -25px; top: 20px; width: 2px; height: calc(100% + 20px); background-color: #dee2e6;
      }
      .timeline-item:last-child::before { display: none; }
      .timeline-marker {
        position: absolute; left: -30px; top: 15px; width: 20px; height: 20px;
        background-color: #007bff; border-radius: 50%; display: flex; align-items: center;
        justify-content: center; color: white; font-size: 10px; z-index: 1;
      }
      .timeline-item.active .timeline-marker { background-color: #28a745; transform: scale(1.2); }
      .timeline-content { margin-left: 10px; }
      .timeline-item.active .card { border-color: #28a745; box-shadow: 0 0 0 0.2rem rgba(40, 167, 69, 0.25); }
      `}</style>
    </div>
  );
};

export default BatchTrackingMap;
