import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import firebaseService from '../services/firebaseService.jsx';
import { useLanguage } from '../context/LanguageContext.jsx';
import { useTheme } from '../context/ThemeContext.jsx';

const ECommerceHome = ({ user }) => {
  const { t } = useLanguage();
  useTheme(); // For theme context
  const [featuredProducts, setFeaturedProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [stats, setStats] = useState({
    totalProducts: 0,
    totalFarmers: 0,
    totalOrders: 0
  });

  useEffect(() => {
    loadHomeData();
  }, []);

  const loadHomeData = async () => {
    try {
      const batches = await firebaseService.getAllAvailableBatches();
      
      // Featured products (top 6)
      const featured = batches.slice(0, 6).map(batch => ({
        id: batch.batchId,
        name: `Premium ${batch.woolType} Wool`,
        price: batch.price,
        grade: batch.qualityGrade || 'A',
        seller: batch.farmerName,
        weight: batch.weight,
        rating: (Math.random() * 2 + 3).toFixed(1)
      }));
      setFeaturedProducts(featured);

      // Categories
      const woolTypes = [...new Set(batches.map(b => b.woolType))];
      setCategories(woolTypes.map(type => ({
        name: type,
        count: batches.filter(b => b.woolType === type).length,
        image: '/api/placeholder/200/150'
      })));

      // Stats
      setStats({
        totalProducts: batches.length,
        totalFarmers: new Set(batches.map(b => b.farmerName)).size,
        totalOrders: Math.floor(Math.random() * 500) + 100
      });
    } catch (error) {
      console.error('Error loading home data:', error);
      // Fallback mock data
      setFeaturedProducts([
        { id: 'mock-1', name: 'Premium Merino Wool', price: 45.99, grade: 'A+', seller: 'Green Valley Farm', weight: 25, rating: '4.8' },
        { id: 'mock-2', name: 'Premium Romney Wool', price: 38.50, grade: 'A', seller: 'Highland Ranch', weight: 30, rating: '4.6' },
        { id: 'mock-3', name: 'Premium Corriedale Wool', price: 42.00, grade: 'A+', seller: 'Mountain View Farm', weight: 20, rating: '4.7' }
      ]);
      setCategories([
        { name: 'Merino', count: 15, image: '/api/placeholder/200/150' },
        { name: 'Romney', count: 12, image: '/api/placeholder/200/150' },
        { name: 'Corriedale', count: 8, image: '/api/placeholder/200/150' }
      ]);
      setStats({ totalProducts: 35, totalFarmers: 18, totalOrders: 247 });
    }
  };

  return (
    <div>
      {/* Hero Section */}
      <section className="hero-section text-white py-5">
        <div className="container">
          <div className="row align-items-center">
            <div className="col-lg-6">
              <h1 className="display-4 fw-bold mb-4">{t('woolMonitor')}</h1>
              <p className="lead mb-4">
                Connect directly with verified wool farmers. Quality guaranteed, 
                blockchain tracked, from farm to fabric.
              </p>
              <div className="d-flex gap-3">
                <Link to="/products" className="btn btn-light btn-lg">
                  <i className="fas fa-shopping-bag me-2"></i>{t('shopNow')}
                </Link>
                <Link to="/traceability" className="btn btn-outline-light btn-lg">
                  <i className="fas fa-route me-2"></i>Track Wool
                </Link>
              </div>
            </div>
            <div className="col-lg-6 text-center">
              <i className="fas fa-sheep fa-10x opacity-75"></i>
            </div>
          </div>
        </div>
      </section>

      {/* Stats Section */}
      <section className="section section-alt">
        <div className="container">
          <div className="row text-center">
            <div className="col-md-4 mb-4">
              <div className="stats-card fade-in-up">
                <div className="stats-icon">
                  <i className="fas fa-boxes fa-2x text-white"></i>
                </div>
                <h3 className="fw-bold text-primary">{stats.totalProducts}+</h3>
                <p className="text-muted">Quality Products</p>
              </div>
            </div>
            <div className="col-md-4 mb-4">
              <div className="stats-card fade-in-up">
                <div className="stats-icon" style={{background: 'linear-gradient(135deg, var(--secondary-color) 0%, var(--secondary-light) 100%)'}}>
                  <i className="fas fa-users fa-2x text-white"></i>
                </div>
                <h3 className="fw-bold text-primary">{stats.totalFarmers}+</h3>
                <p className="text-muted">Verified Farmers</p>
              </div>
            </div>
            <div className="col-md-4 mb-4">
              <div className="stats-card fade-in-up">
                <div className="stats-icon" style={{background: 'linear-gradient(135deg, #f59e0b 0%, #fbbf24 100%)'}}>
                  <i className="fas fa-shopping-cart fa-2x text-white"></i>
                </div>
                <h3 className="fw-bold text-primary">{stats.totalOrders}+</h3>
                <p className="text-muted">Happy Customers</p>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Categories Section */}
      <section className="section">
        <div className="container">
          <h2 className="text-center mb-5">Shop by Category</h2>
          <div className="row">
            {categories.map(category => (
              <div key={category.name} className="col-lg-4 col-md-6 mb-4">
                <div className="card h-100">
                  <div className="product-image" style={{height: '150px'}}>
                    <i className="fas fa-cut fa-3x text-muted"></i>
                  </div>
                  <div className="card-body text-center">
                    <h5 className="card-title">{category.name} Wool</h5>
                    <p className="text-muted">{category.count} products available</p>
                    <Link to={`/products?category=${category.name}`} className="btn btn-outline-primary">
                      Shop {category.name}
                    </Link>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Featured Products */}
      <section className="section section-alt">
        <div className="container">
          <div className="d-flex justify-content-between align-items-center mb-5">
            <h2>Featured Products</h2>
            <Link to="/products" className="btn btn-primary">
              View All Products <i className="fas fa-arrow-right ms-2"></i>
            </Link>
          </div>
          
          <div className="row">
            {featuredProducts.map(product => (
              <div key={product.id} className="col-lg-4 col-md-6 mb-4">
                <div className="product-card h-100">
                  <div className="position-relative">
                    <div className="product-image" style={{height: '200px'}}>
                      <i className="fas fa-image fa-3x text-muted"></i>
                    </div>
                    <span className={`position-absolute top-0 end-0 m-2 badge bg-${product.grade === 'A+' ? 'success' : 'primary'}`}>
                      {product.grade} Grade
                    </span>
                  </div>
                  
                  <div className="card-body">
                    <h6 className="card-title">{product.name}</h6>
                    <p className="text-muted small">{product.seller}</p>
                    
                    <div className="d-flex justify-content-between align-items-center mb-3">
                      <span className="h5 text-success mb-0">${product.price}/kg</span>
                      <div>
                        <i className="fas fa-star text-warning"></i>
                        <small>{product.rating}</small>
                      </div>
                    </div>
                    
                    <div className="d-flex gap-2">
                      <Link to={`/products/${product.id}`} className="btn btn-outline-primary flex-fill">
                        View Details
                      </Link>
                      <button className="btn btn-primary" disabled={!user} title={!user ? 'Login required' : 'Add to cart'}>
                        <i className="fas fa-cart-plus"></i>
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Features Section */}
      <section className="section">
        <div className="container">
          <h2 className="text-center mb-5">Why Choose Our Platform?</h2>
          <div className="row">
            <div className="col-lg-3 col-md-6 mb-4">
              <div className="text-center">
                <div className="bg-primary text-white rounded-circle d-inline-flex align-items-center justify-content-center mb-3" style={{width: '80px', height: '80px'}}>
                  <i className="fas fa-shield-alt fa-2x"></i>
                </div>
                <h5>Quality Guaranteed</h5>
                <p className="text-muted">AI-powered quality assessment ensures premium wool standards</p>
              </div>
            </div>
            <div className="col-lg-3 col-md-6 mb-4">
              <div className="text-center">
                <div className="bg-success text-white rounded-circle d-inline-flex align-items-center justify-content-center mb-3" style={{width: '80px', height: '80px'}}>
                  <i className="fas fa-link fa-2x"></i>
                </div>
                <h5>Blockchain Tracked</h5>
                <p className="text-muted">Complete traceability from farm to fabric with immutable records</p>
              </div>
            </div>
            <div className="col-lg-3 col-md-6 mb-4">
              <div className="text-center">
                <div className="bg-warning text-white rounded-circle d-inline-flex align-items-center justify-content-center mb-3" style={{width: '80px', height: '80px'}}>
                  <i className="fas fa-handshake fa-2x"></i>
                </div>
                <h5>Direct from Farmers</h5>
                <p className="text-muted">Connect directly with verified farmers for the best prices</p>
              </div>
            </div>
            <div className="col-lg-3 col-md-6 mb-4">
              <div className="text-center">
                <div className="bg-info text-white rounded-circle d-inline-flex align-items-center justify-content-center mb-3" style={{width: '80px', height: '80px'}}>
                  <i className="fas fa-shipping-fast fa-2x"></i>
                </div>
                <h5>Fast Delivery</h5>
                <p className="text-muted">Quick and secure shipping with real-time tracking</p>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section className="hero-section text-white">
        <div className="container text-center">
          <h2 className="mb-4">Ready to Start Trading?</h2>
          <p className="lead mb-4">Join thousands of satisfied customers and farmers on our platform</p>
          <div className="d-flex justify-content-center gap-3">
            {!user && (
              <Link to="/login" className="btn btn-light btn-lg">
                <i className="fas fa-user-plus me-2"></i>Sign Up Now
              </Link>
            )}
            <Link to="/products" className="btn btn-outline-light btn-lg">
              <i className="fas fa-shopping-bag me-2"></i>Browse Products
            </Link>
          </div>
        </div>
      </section>
    </div>
  );
};

export default ECommerceHome;