import React, { useState } from 'react';
import woolQualityService from '../services/woolQualityService.jsx';
import { analyzeWoolQuality } from '../services/aiQualityService.jsx';

const WoolQualityForm = ({ batchId, onSave }) => {
  const [quality, setQuality] = useState({
    color: '',
    stapleLength: '',
    micron: '',
    strength: '',
    vegetableMatter: '',
    moisture: '',
    yield: '',
    notes: '',
  });
  const [loading, setLoading] = useState(false);
  const [imageFile, setImageFile] = useState(null);

  const handleChange = (e) => {
    setQuality({ ...quality, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      // Ensure numeric fields are passed as numbers
      const payload = {
        ...quality,
        stapleLength: Number(quality.stapleLength),
        micron: Number(quality.micron),
        moisture: Number(quality.moisture),
        yield: Number(quality.yield),
      };
      // Optional AI analysis on uploaded image
      let aiAnalysis = null;
      if (imageFile) {
        try {
          aiAnalysis = await analyzeWoolQuality(imageFile);
        } catch (aiErr) {
          console.warn('AI analysis failed, continuing with rule-based scoring:', aiErr);
        }
      }
      if (aiAnalysis) {
        payload.ai = aiAnalysis;
      }
      await woolQualityService.addQualityRecord(batchId, payload);
      setQuality({ color: '', stapleLength: '', micron: '', strength: '', vegetableMatter: '', moisture: '', yield: '', notes: '' });
      setImageFile(null);
      if (onSave) onSave();
      alert('Quality record saved.');
    } catch (err) {
      alert('Error saving quality record: ' + err.message);
    }
    setLoading(false);
  };

  return (
    <form onSubmit={handleSubmit}>
      <div className="mb-2">
        <label className="form-label">Color</label>
        <input name="color" className="form-control" value={quality.color} onChange={handleChange} required />
      </div>
      <div className="mb-2">
        <label className="form-label">Wool Image (optional, improves AI assessment)</label>
        <input type="file" accept="image/*" className="form-control" onChange={(e)=> setImageFile(e.target.files?.[0] || null)} />
      </div>
      <div className="mb-2">
        <label className="form-label">Staple Length (mm)</label>
        <input name="stapleLength" className="form-control" value={quality.stapleLength} onChange={handleChange} required type="number" min="0" />
      </div>
      <div className="mb-2">
        <label className="form-label">Micron (µm)</label>
        <input name="micron" className="form-control" value={quality.micron} onChange={handleChange} required type="number" min="0" step="0.01" />
      </div>
      <div className="mb-2">
        <label className="form-label">Strength</label>
        <input name="strength" className="form-control" value={quality.strength} onChange={handleChange} required />
      </div>
      <div className="mb-2">
        <label className="form-label">Vegetable Matter</label>
        <input name="vegetableMatter" className="form-control" value={quality.vegetableMatter} onChange={handleChange} required />
      </div>
      <div className="mb-2">
        <label className="form-label">Moisture (%)</label>
        <input name="moisture" className="form-control" value={quality.moisture} onChange={handleChange} required type="number" min="0" step="0.01" />
      </div>
      <div className="mb-2">
        <label className="form-label">Yield (%)</label>
        <input name="yield" className="form-control" value={quality.yield} onChange={handleChange} required type="number" min="0" step="0.01" />
      </div>
      <div className="mb-2">
        <label className="form-label">Notes</label>
        <textarea name="notes" className="form-control" value={quality.notes} onChange={handleChange} rows={2} />
      </div>
      <button className="btn btn-success w-100" type="submit" disabled={loading}>{loading ? 'Saving…' : 'Save Quality Record'}</button>
    </form>
  );
};
export default WoolQualityForm;
