import React from 'react';

const WoolQualityDetails = ({ quality }) => {
  if (!quality) return <div className="text-muted small">No quality record available</div>;
  return (
    <div className="card border-info mb-2">
      <div className="card-header bg-info text-white">Wool Quality Parameters</div>
      <div className="card-body">
        {(quality.grade || quality.score) && (
          <div className="row mb-2">
            <div className="col-6"><strong>Grade:</strong> {quality.grade || '—'}</div>
            <div className="col-6"><strong>Score:</strong> {quality.score ?? '—'}</div>
          </div>
        )}
        {quality.ai && (
          <div className="row mb-2">
            <div className="col-6"><strong>AI Grade:</strong> {quality.ai.grade || quality.ai.category || '—'}</div>
            <div className="col-6"><strong>AI Score:</strong> {quality.ai.score ?? '—'}</div>
          </div>
        )}
        {quality.indianModel && (
          <div className="mb-2">
            <div className="row">
              <div className="col-6"><strong>Indian Count Grade:</strong> {quality.indianModel.indianCountGrade}</div>
              <div className="col-6"><strong>BIS Category:</strong> {quality.indianModel.bisCategory}</div>
            </div>
            <div className="row">
              <div className="col-6"><strong>FAO Style:</strong> {quality.indianModel.faoStyle}</div>
              <div className="col-6"><strong>Burr Class:</strong> {quality.indianModel.burrClass}</div>
            </div>
            <div className="row">
              <div className="col-12"><strong>Recommendation:</strong> {quality.indianModel.recommendation}</div>
            </div>
            {quality.indianModel.reasons && quality.indianModel.reasons.length > 0 && (
              <div className="row">
                <div className="col-12 small text-muted">
                  <strong>Adjustments:</strong> {quality.indianModel.reasons.join(', ')}
                </div>
              </div>
            )}
          </div>
        )}
        <div className="row">
          <div className="col-6"><strong>Color:</strong> {quality.color}</div>
          <div className="col-6"><strong>Staple Length:</strong> {quality.stapleLength} mm</div>
        </div>
        <div className="row">
          <div className="col-6"><strong>Micron:</strong> {quality.micron} µm</div>
          <div className="col-6"><strong>Strength:</strong> {quality.strength}</div>
        </div>
        <div className="row">
          <div className="col-6"><strong>Vegetable Matter:</strong> {quality.vegetableMatter}</div>
          <div className="col-6"><strong>Moisture:</strong> {quality.moisture} %</div>
        </div>
        <div className="row">
          <div className="col-6"><strong>Yield:</strong> {quality.yield} %</div>
          <div className="col-6"><strong>Assessor:</strong> {quality.createdBy || 'N/A'}</div>
        </div>
        <div className="row">
          <div className="col-12"><strong>Notes:</strong> {quality.notes}</div>
        </div>
      </div>
    </div>
  );
};
export default WoolQualityDetails;
