import React, { useState, useEffect } from 'react';
import firebaseService from '../services/firebaseService.jsx';

const SimpleMarketplace = ({ user }) => {
  const [batches, setBatches] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadBatches();
  }, []);

  const loadBatches = async () => {
    try {
      const availableBatches = await firebaseService.getAllAvailableBatches();
      setBatches(availableBatches);
    } catch (error) {
      console.error('Error loading batches:', error);
    } finally {
      setLoading(false);
    }
  };

  const handlePurchase = async (batch) => {
    if (!user) {
      alert('Please log in to purchase');
      return;
    }

    try {
      const orderData = {
        items: [{
          batchId: batch.batchId,
          name: batch.batchName || `${batch.woolType} Wool`,
          price: batch.price,
          quantity: 1,
          total: batch.price
        }],
        totalAmount: batch.price,
        paymentMethod: 'Card',
        shippingAddress: 'Default Address'
      };

      await firebaseService.createOrder(orderData);
      alert('Order placed successfully!');
      loadBatches(); // Refresh batches
    } catch (error) {
      console.error('Error placing order:', error);
      alert('Failed to place order');
    }
  };

  if (loading) {
    return (
      <div className="container py-5 text-center">
        <div className="spinner-border text-primary"></div>
        <p className="mt-2">Loading marketplace...</p>
      </div>
    );
  }

  return (
    <div className="container py-4">
      <div className="row mb-4">
        <div className="col-12">
          <h2>Wool Marketplace</h2>
          <p className="text-muted">Available wool batches from farmers</p>
        </div>
      </div>

      <div className="row">
        {batches.map(batch => (
          <div key={batch.id} className="col-md-4 mb-4">
            <div className="card">
              <div className="card-body">
                <h5 className="card-title">{batch.batchName || `${batch.woolType} Wool`}</h5>
                <p className="card-text">
                  <strong>Farmer:</strong> {batch.farmerName}<br/>
                  <strong>Type:</strong> {batch.woolType}<br/>
                  <strong>Weight:</strong> {batch.weight} kg<br/>
                  <strong>Location:</strong> {batch.location}<br/>
                  <strong>Price:</strong> ${batch.price}/kg
                </p>
                {user?.role === 'buyer' && (
                  <button 
                    className="btn btn-primary"
                    onClick={() => handlePurchase(batch)}
                  >
                    Purchase
                  </button>
                )}
                {user?.role === 'farmer' && batch.farmerId === user.uid && (
                  <span className="badge bg-success">Your Batch</span>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      {batches.length === 0 && (
        <div className="text-center py-5">
          <h5 className="text-muted">No batches available</h5>
          <p className="text-muted">Check back later for new wool batches</p>
        </div>
      )}
    </div>
  );
};

export default SimpleMarketplace;