import React, { useState, useEffect } from 'react';
import { useLanguage } from '../context/LanguageContext.jsx';
import storageRecordsService from '../services/storageRecordsService.jsx';

const StorageProcessing = ({ user }) => {
  const { t } = useLanguage();
  const [storageForm, setStorageForm] = useState({
    batchId: '',
    warehouseName: '',
    location: '',
    temperature: '',
    humidity: ''
  });
  
  const [processingForm, setProcesssingForm] = useState({
    batchId: '',
    processType: '',
    startDate: '',
    expectedCompletion: '',
    notes: ''
  });

  const [storageRecords, setStorageRecords] = useState([]);
  const [processingRecords, setProcessingRecords] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (user) {
      loadUserRecords();
    }
  }, [user]);

  const loadUserRecords = () => {
    try {
      setLoading(true);
      const userId = user.id || user.uid || user.username || 'demo-user';
      
      const unsubscribeStorage = storageRecordsService.getUserStorageRecords(userId, (records) => {
        setStorageRecords(records);
        setLoading(false);
      });
      
      const unsubscribeProcessing = storageRecordsService.getUserProcessingRecords(userId, (records) => {
        setProcessingRecords(records);
      });
      
      return () => {
        if (unsubscribeStorage) unsubscribeStorage();
        if (unsubscribeProcessing) unsubscribeProcessing();
      };
    } catch (error) {
      console.error('Error loading records:', error);
      setError('Failed to load records');
      setStorageRecords(storageRecordsService.getMockStorageRecords());
      setProcessingRecords(storageRecordsService.getMockProcessingRecords());
      setLoading(false);
    }
  };

  const handleStorageSubmit = async (e) => {
    e.preventDefault();
    try {
      const userId = user.id || user.uid || user.username || 'demo-user';
      const result = await storageRecordsService.saveStorageRecord(storageForm, userId);
      
      if (result.success) {
        alert('Storage details recorded successfully!');
        setStorageForm({
          batchId: '',
          warehouseName: '',
          location: '',
          temperature: '',
          humidity: ''
        });
      } else {
        alert('Error saving storage record: ' + result.error);
      }
    } catch (error) {
      console.error('Error submitting storage form:', error);
      alert('Error saving storage record');
    }
  };

  const handleProcessingSubmit = async (e) => {
    e.preventDefault();
    try {
      const userId = user.id || user.uid || user.username || 'demo-user';
      const result = await storageRecordsService.saveProcessingRecord(processingForm, userId);
      
      if (result.success) {
        alert('Processing step recorded successfully!');
        setProcesssingForm({
          batchId: '',
          processType: '',
          startDate: '',
          expectedCompletion: '',
          notes: ''
        });
      } else {
        alert('Error saving processing record: ' + result.error);
      }
    } catch (error) {
      console.error('Error submitting processing form:', error);
      alert('Error saving processing record');
    }
  };

  return (
    <div className="container-fluid py-4">
      {/* Header */}
      <div className="row mb-4">
        <div className="col-12">
          <div className="card bg-gradient-primary text-white border-0">
            <div className="card-body">
              <div className="row align-items-center">
                <div className="col-md-8">
                  <h3 className="mb-2">
                    <i className="fas fa-warehouse me-3"></i>
                    {t('storageProcessingManagement')}
                  </h3>
                  <p className="mb-0 opacity-75">Monitor storage conditions and track processing steps</p>
                </div>
                <div className="col-md-4 text-end">
                  <div className="badge bg-white text-primary px-3 py-2 rounded-pill">
                    <i className="fas fa-user-tag me-2"></i>
                    Role: {user.role}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      
      {/* Stats Cards */}
      <div className="row mb-4">
        <div className="col-md-3">
          <div className="card bg-info text-white border-0">
            <div className="card-body text-center py-4">
              <i className="fas fa-warehouse fa-2x mb-3"></i>
              <h4 className="mb-1">{storageRecords.length}</h4>
              <small>Storage Records</small>
            </div>
          </div>
        </div>
        <div className="col-md-3">
          <div className="card bg-success text-white border-0">
            <div className="card-body text-center py-4">
              <i className="fas fa-cogs fa-2x mb-3"></i>
              <h4 className="mb-1">{processingRecords.length}</h4>
              <small>Processing Steps</small>
            </div>
          </div>
        </div>
        <div className="col-md-3">
          <div className="card bg-warning text-white border-0">
            <div className="card-body text-center py-4">
              <i className="fas fa-check-circle fa-2x mb-3"></i>
              <h4 className="mb-1">{processingRecords.filter(r => r.status === 'Completed').length}</h4>
              <small>Completed</small>
            </div>
          </div>
        </div>
        <div className="col-md-3">
          <div className="card bg-secondary text-white border-0">
            <div className="card-body text-center py-4">
              <i className="fas fa-clock fa-2x mb-3"></i>
              <h4 className="mb-1">{processingRecords.filter(r => r.status === 'In Progress').length}</h4>
              <small>In Progress</small>
            </div>
          </div>
        </div>
      </div>
      
      <div className="row mt-4">
        {/* Storage Form */}
        {(user.role === 'farmer' || user.role === 'government') && (
          <div className="col-md-6">
            <div className="card border-0 shadow-sm h-100">
              <div className="card-header bg-success text-white">
                <h5 className="mb-0"><i className="fas fa-warehouse me-2"></i>Record Storage Details</h5>
              </div>
              <div className="card-body">
                <form onSubmit={handleStorageSubmit}>
                  <div className="mb-3">
                    <label className="form-label fw-semibold">
                      <i className="fas fa-hashtag me-2 text-primary"></i>Batch ID
                    </label>
                    <input
                      type="text"
                      className="form-control form-control-lg border-2"
                      value={storageForm.batchId}
                      onChange={(e) => setStorageForm({...storageForm, batchId: e.target.value})}
                      required
                    />
                  </div>
                  
                  <div className="mb-3">
                    <label className="form-label fw-semibold">
                      <i className="fas fa-building me-2 text-info"></i>Warehouse Name
                    </label>
                    <input
                      type="text"
                      className="form-control form-control-lg border-2"
                      value={storageForm.warehouseName}
                      onChange={(e) => setStorageForm({...storageForm, warehouseName: e.target.value})}
                      required
                    />
                  </div>
                  
                  <div className="mb-3">
                    <label className="form-label fw-semibold">
                      <i className="fas fa-map-marker-alt me-2 text-warning"></i>Location
                    </label>
                    <input
                      type="text"
                      className="form-control form-control-lg border-2"
                      value={storageForm.location}
                      onChange={(e) => setStorageForm({...storageForm, location: e.target.value})}
                      required
                    />
                  </div>
                  
                  <div className="row">
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label className="form-label fw-semibold">
                          <i className="fas fa-thermometer-half me-2 text-danger"></i>Temperature (°C)
                        </label>
                        <input
                          type="number"
                          className="form-control form-control-lg border-2"
                          value={storageForm.temperature}
                          onChange={(e) => setStorageForm({...storageForm, temperature: e.target.value})}
                          required
                        />
                      </div>
                    </div>
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label className="form-label fw-semibold">
                          <i className="fas fa-tint me-2 text-info"></i>Humidity (%)
                        </label>
                        <input
                          type="number"
                          className="form-control form-control-lg border-2"
                          value={storageForm.humidity}
                          onChange={(e) => setStorageForm({...storageForm, humidity: e.target.value})}
                          required
                        />
                      </div>
                    </div>
                  </div>
                  
                  <button type="submit" className="btn btn-primary btn-lg w-100 rounded-pill shadow-lg">
                    <i className="fas fa-save me-2"></i>Record Storage
                  </button>
                </form>
              </div>
            </div>
          </div>
        )}
        
        {/* Processing Form */}
        {(user.role === 'farmer' || user.role === 'government') && (
          <div className="col-md-6">
            <div className="card border-0 shadow-sm h-100">
              <div className="card-header bg-warning text-white">
                <h5 className="mb-0"><i className="fas fa-cogs me-2"></i>Record Processing Step</h5>
              </div>
              <div className="card-body">
                <form onSubmit={handleProcessingSubmit}>
                  <div className="mb-3">
                    <label className="form-label fw-semibold">
                      <i className="fas fa-hashtag me-2 text-primary"></i>Batch ID
                    </label>
                    <input
                      type="text"
                      className="form-control form-control-lg border-2"
                      value={processingForm.batchId}
                      onChange={(e) => setProcesssingForm({...processingForm, batchId: e.target.value})}
                      required
                    />
                  </div>
                  
                  <div className="mb-3">
                    <label className="form-label fw-semibold">
                      <i className="fas fa-industry me-2 text-info"></i>Process Type
                    </label>
                    <select
                      className="form-select form-select-lg border-2"
                      value={processingForm.processType}
                      onChange={(e) => setProcesssingForm({...processingForm, processType: e.target.value})}
                      required
                    >
                      <option value="">Select Process</option>
                      <option value="Scouring">Scouring</option>
                      <option value="Sorting">Sorting</option>
                      <option value="Carding">Carding</option>
                      <option value="Combing">Combing</option>
                      <option value="Dyeing">Dyeing</option>
                      <option value="Spinning">Spinning</option>
                    </select>
                  </div>
                  
                  <div className="row">
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label className="form-label fw-semibold">
                          <i className="fas fa-play me-2 text-success"></i>Start Date
                        </label>
                        <input
                          type="date"
                          className="form-control form-control-lg border-2"
                          value={processingForm.startDate}
                          onChange={(e) => setProcesssingForm({...processingForm, startDate: e.target.value})}
                          required
                        />
                      </div>
                    </div>
                    <div className="col-md-6">
                      <div className="mb-3">
                        <label className="form-label fw-semibold">
                          <i className="fas fa-flag-checkered me-2 text-danger"></i>Expected Completion
                        </label>
                        <input
                          type="date"
                          className="form-control form-control-lg border-2"
                          value={processingForm.expectedCompletion}
                          onChange={(e) => setProcesssingForm({...processingForm, expectedCompletion: e.target.value})}
                          required
                        />
                      </div>
                    </div>
                  </div>
                  
                  <div className="mb-3">
                    <label className="form-label fw-semibold">
                      <i className="fas fa-sticky-note me-2 text-warning"></i>Notes
                    </label>
                    <textarea
                      className="form-control border-2"
                      rows="3"
                      value={processingForm.notes}
                      onChange={(e) => setProcesssingForm({...processingForm, notes: e.target.value})}
                    ></textarea>
                  </div>
                  
                  <button type="submit" className="btn btn-success btn-lg w-100 rounded-pill shadow-lg">
                    <i className="fas fa-cogs me-2"></i>Record Process
                  </button>
                </form>
              </div>
            </div>
          </div>
        )}
      </div>
      
      {/* Storage Records */}
      <div className="row mt-4">
        <div className="col-md-6">
          <div className="card border-0 shadow-sm">
            <div className="card-header bg-info text-white">
              <h5 className="mb-0"><i className="fas fa-list me-2"></i>Storage Records</h5>
            </div>
            <div className="card-body">
              {loading ? (
                <div className="text-center py-4">
                  <div className="spinner-border text-primary" role="status">
                    <span className="visually-hidden">Loading...</span>
                  </div>
                  <p className="text-muted mt-2">Loading storage records...</p>
                </div>
              ) : error ? (
                <div className="alert alert-warning">
                  <i className="fas fa-exclamation-triangle me-2"></i>
                  {error} - Showing demo data
                </div>
              ) : null}
              
              <div className="table-responsive">
                <table className="table table-sm">
                  <thead>
                    <tr>
                      <th>Batch ID</th>
                      <th>Warehouse</th>
                      <th>Temp/Humidity</th>
                      <th>Status</th>
                      <th>Date</th>
                    </tr>
                  </thead>
                  <tbody>
                    {storageRecords.length > 0 ? storageRecords.map((record, index) => (
                      <tr key={record.id || index}>
                        <td><strong className="text-primary">{record.batchId}</strong></td>
                        <td>
                          {record.warehouseName}<br/>
                          <small className="text-muted">{record.location}</small>
                        </td>
                        <td>
                          {record.temperature}°C<br/>
                          <small className="text-muted">{record.humidity}%</small>
                        </td>
                        <td>
                          <span className={`badge ${record.status === 'Stored' ? 'bg-success' : 'bg-warning'}`}>
                            {record.status}
                          </span>
                        </td>
                        <td>
                          <small className="text-muted">
                            {new Date(record.createdAt).toLocaleDateString()}
                          </small>
                        </td>
                      </tr>
                    )) : (
                      <tr>
                        <td colSpan="5" className="text-center text-muted py-3">
                          <i className="fas fa-inbox fa-2x mb-2 d-block"></i>
                          No storage records found
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
        
        {/* Processing Timeline */}
        <div className="col-md-6">
          <div className="card border-0 shadow-sm">
            <div className="card-header bg-secondary text-white">
              <h5 className="mb-0"><i className="fas fa-timeline me-2"></i>Processing Timeline</h5>
            </div>
            <div className="card-body">
              {loading ? (
                <div className="text-center py-4">
                  <div className="spinner-border text-primary" role="status">
                    <span className="visually-hidden">Loading...</span>
                  </div>
                  <p className="text-muted mt-2">Loading processing records...</p>
                </div>
              ) : processingRecords.length > 0 ? (
                processingRecords.map((record, index) => (
                  <div key={record.id || index} className="d-flex align-items-center mb-3">
                    <div className={`badge ${record.status === 'Completed' ? 'bg-success' : 
                                            record.status === 'In Progress' ? 'bg-warning' : 'bg-secondary'} me-3`}>
                      {index + 1}
                    </div>
                    <div className="flex-grow-1">
                      <strong>{record.processType}</strong> - {record.batchId}<br/>
                      <small className="text-muted">Started: {record.startDate}</small>
                      {record.notes && (
                        <div className="small text-info mt-1">
                          <i className="fas fa-sticky-note me-1"></i>{record.notes}
                        </div>
                      )}
                      <div className="progress mt-1" style={{height: '4px'}}>
                        <div 
                          className="progress-bar" 
                          style={{width: record.completion || '0%'}}
                        ></div>
                      </div>
                    </div>
                    <div className="text-end">
                      <span className={`badge ${record.status === 'Completed' ? 'bg-success' : 
                                              record.status === 'In Progress' ? 'bg-warning' : 'bg-secondary'} d-block mb-1`}>
                        {record.status}
                      </span>
                      <small className="text-muted">
                        {new Date(record.createdAt).toLocaleDateString()}
                      </small>
                    </div>
                  </div>
                ))
              ) : (
                <div className="text-center py-4 text-muted">
                  <i className="fas fa-cogs fa-3x mb-3 opacity-50"></i>
                  <h6>No Processing Records</h6>
                  <p className="small">Start processing wool batches to see timeline</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StorageProcessing;