import React, { useState, useEffect } from 'react';

const ConnectionStatus = () => {
  const [isOnline, setIsOnline] = useState(true);
  const [showStatus, setShowStatus] = useState(false);

  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      setShowStatus(true);
      setTimeout(() => setShowStatus(false), 3000);
    };

    const handleOffline = () => {
      setIsOnline(false);
      setShowStatus(true);
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  if (!showStatus && isOnline) return null;

  return (
    <div className={`alert ${isOnline ? 'alert-success' : 'alert-warning'} alert-dismissible fade show`}>
      <i className={`fas fa-${isOnline ? 'wifi' : 'exclamation-triangle'} me-2`}></i>
      <strong>{isOnline ? 'Online:' : 'Offline:'}</strong> 
      {isOnline ? ' Connected to Firebase' : ' Using local storage'}
      {showStatus && isOnline && (
        <button type="button" className="btn-close" onClick={() => setShowStatus(false)}></button>
      )}
    </div>
  );
};

export default ConnectionStatus;