import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext.jsx';
import { useTheme } from '../context/ThemeContext.jsx';
import ThemeToggle from './ThemeToggle.jsx';

const Navbar = ({ user, onLogout }) => {
  const navigate = useNavigate();
  const { t, changeLanguage, languages, currentLanguage } = useLanguage();
  useTheme(); // For theme context
  const [showLanguageDropdown, setShowLanguageDropdown] = useState(false);

  const handleLogout = () => {
    onLogout();
    navigate('/');
  };

  return (
    <nav className="navbar navbar-expand-lg navbar-dark">
      <div className="container">
        <Link className="navbar-brand pulse" to="/">
          <i className="fas fa-sheep me-2"></i>
          {t('woolMonitor')}
        </Link>
        <button className="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarNav">
          <span className="navbar-toggler-icon"></span>
        </button>
        
        <div className="collapse navbar-collapse" id="navbarNav">
          <ul className="navbar-nav me-auto">
            <li className="nav-item">
              <Link className="nav-link" to="/products">Products</Link>
            </li>
            {user && (
              <>
                {user.role === 'farmer' && (
                  <>
                    <li className="nav-item">
                      <Link className="nav-link" to="/dashboard">Dashboard</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/traceability">Batches</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/marketplace">Marketplace</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/processing">Processing</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/storage">Storage</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/education">Training</Link>
                    </li>
                  </>
                )}
                {user.role === 'inspector' && (
                  <>
                    <li className="nav-item">
                      <Link className="nav-link" to="/inspect">Assess Batches</Link>
                    </li>
                  </>
                )}
                {user.role === 'buyer' && (
                  <>
                    <li className="nav-item">
                      <Link className="nav-link" to="/dashboard">Dashboard</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/products">Products</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/cart">Cart</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/processing">Processing</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/orders">Orders</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/education">Training</Link>
                    </li>
                  </>
                )}
                {user.role === 'government' && (
                  <>
                    <li className="nav-item">
                      <Link className="nav-link" to="/dashboard">Dashboard</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/government">Admin Panel</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/inspect">Assess Batches</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/market-info">Market Info</Link>
                    </li>
                    <li className="nav-item">
                      <Link className="nav-link" to="/education">Training</Link>
                    </li>
                  </>
                )}
              </>
            )}
          </ul>
          
          <ul className="navbar-nav align-items-center">
            {/* Theme Toggle */}
            <li className="nav-item me-3">
              <ThemeToggle />
            </li>
            
            {/* Language Selector */}
            <li className="nav-item language-selector me-3">
              <button 
                className="nav-link btn btn-link text-white"
                onClick={() => setShowLanguageDropdown(!showLanguageDropdown)}
              >
                <i className="fas fa-globe me-1"></i>
                {languages.find(lang => lang.code === currentLanguage)?.flag}
              </button>
              {showLanguageDropdown && (
                <div className="language-dropdown">
                  {languages.map(lang => (
                    <div 
                      key={lang.code}
                      className="language-option"
                      onClick={() => {
                        changeLanguage(lang.code);
                        setShowLanguageDropdown(false);
                      }}
                    >
                      <span className="me-2">{lang.flag}</span>
                      {lang.name}
                    </div>
                  ))}
                </div>
              )}
            </li>
            
            {user ? (
              <li className="nav-item dropdown">
                <button className="nav-link dropdown-toggle btn btn-link text-white" type="button" data-bs-toggle="dropdown" aria-expanded="false">
                  <i className="fas fa-user me-1"></i>
                  {user.name} 
                  <span className="badge bg-primary ms-1">{user.role}</span>
                </button>
                <ul className="dropdown-menu dropdown-menu-end">
                  <li><Link className="dropdown-item" to="/profile"><i className="fas fa-user-edit me-2"></i>Profile</Link></li>
                  <li><hr className="dropdown-divider" /></li>
                  <li><button className="dropdown-item" onClick={handleLogout}><i className="fas fa-sign-out-alt me-2"></i>Logout</button></li>
                </ul>
              </li>
            ) : (
              <li className="nav-item">
                <Link className="nav-link btn btn-outline-light" to="/login">{t('login')}</Link>
              </li>
            )}
          </ul>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;