import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import firebaseService from '../services/firebaseService.jsx';

const SimpleDashboard = ({ user }) => {
  const [stats, setStats] = useState({
    batches: 0,
    orders: 0,
    revenue: 0
  });

  useEffect(() => {
    loadStats();
  }, [user]);

  const loadStats = async () => {
    if (!user) return;
    
    try {
      if (user.role === 'farmer') {
        const batches = await firebaseService.getFarmerBatches(user.uid);
        const orders = await firebaseService.getUserOrders('seller');
        const revenue = orders.reduce((sum, order) => sum + (order.totalAmount || 0), 0);
        
        setStats({
          batches: batches.length,
          orders: orders.length,
          revenue: revenue
        });
      } else if (user.role === 'buyer') {
        const orders = await firebaseService.getUserOrders('buyer');
        const spent = orders.reduce((sum, order) => sum + (order.totalAmount || 0), 0);
        
        setStats({
          batches: 0,
          orders: orders.length,
          revenue: spent
        });
      }
    } catch (error) {
      console.error('Error loading stats:', error);
    }
  };

  return (
    <div className="container py-4">
      <div className="row mb-4">
        <div className="col-12">
          <h2>Welcome, {user?.name || user?.displayName}!</h2>
          <p className="text-muted">Role: {user?.role}</p>
        </div>
      </div>

      <div className="row">
        {user?.role === 'farmer' && (
          <>
            <div className="col-md-4">
              <div className="card bg-primary text-white">
                <div className="card-body text-center">
                  <i className="fas fa-boxes fa-2x mb-2"></i>
                  <h3>{stats.batches}</h3>
                  <p>Total Batches</p>
                </div>
              </div>
            </div>
            <div className="col-md-4">
              <div className="card bg-success text-white">
                <div className="card-body text-center">
                  <i className="fas fa-shopping-cart fa-2x mb-2"></i>
                  <h3>{stats.orders}</h3>
                  <p>Sales</p>
                </div>
              </div>
            </div>
            <div className="col-md-4">
              <div className="card bg-info text-white">
                <div className="card-body text-center">
                  <i className="fas fa-dollar-sign fa-2x mb-2"></i>
                  <h3>${stats.revenue.toFixed(2)}</h3>
                  <p>Revenue</p>
                </div>
              </div>
            </div>
          </>
        )}

        {user?.role === 'buyer' && (
          <>
            <div className="col-md-6">
              <div className="card bg-primary text-white">
                <div className="card-body text-center">
                  <i className="fas fa-receipt fa-2x mb-2"></i>
                  <h3>{stats.orders}</h3>
                  <p>Total Orders</p>
                </div>
              </div>
            </div>
            <div className="col-md-6">
              <div className="card bg-warning text-white">
                <div className="card-body text-center">
                  <i className="fas fa-credit-card fa-2x mb-2"></i>
                  <h3>${stats.revenue.toFixed(2)}</h3>
                  <p>Total Spent</p>
                </div>
              </div>
            </div>
          </>
        )}
      </div>

      <div className="row mt-4">
        <div className="col-12">
          <div className="card">
            <div className="card-body">
              <h5>Quick Actions</h5>
              <div className="d-flex gap-2 flex-wrap">
                {user?.role === 'farmer' && (
                  <>
                    <Link to="/traceability" className="btn btn-primary">
                      <i className="fas fa-plus me-1"></i>Add Batch
                    </Link>
                    <Link to="/marketplace" className="btn btn-success">
                      <i className="fas fa-store me-1"></i>Marketplace
                    </Link>
                    <Link to="/processing" className="btn btn-warning">
                      <i className="fas fa-cogs me-1"></i>Processing
                    </Link>
                    <Link to="/storage" className="btn btn-info">
                      <i className="fas fa-warehouse me-1"></i>Storage
                    </Link>
                    <Link to="/orders" className="btn btn-secondary">
                      <i className="fas fa-chart-line me-1"></i>Sales
                    </Link>
                    <Link to="/education" className="btn btn-dark">
                      <i className="fas fa-graduation-cap me-1"></i>Training
                    </Link>
                  </>
                )}
                {user?.role === 'buyer' && (
                  <>
                    <Link to="/products" className="btn btn-primary">
                      <i className="fas fa-shopping-bag me-1"></i>Shop Now
                    </Link>
                    <Link to="/cart" className="btn btn-success">
                      <i className="fas fa-shopping-cart me-1"></i>Cart
                    </Link>
                    <Link to="/processing" className="btn btn-warning">
                      <i className="fas fa-cogs me-1"></i>Processing
                    </Link>
                    <Link to="/orders" className="btn btn-info">
                      <i className="fas fa-truck me-1"></i>Track Orders
                    </Link>
                    <Link to="/education" className="btn btn-dark">
                      <i className="fas fa-graduation-cap me-1"></i>Training
                    </Link>
                  </>
                )}
                {user?.role === 'government' && (
                  <>
                    <Link to="/government" className="btn btn-primary">
                      <i className="fas fa-chart-bar me-1"></i>Admin Panel
                    </Link>
                    <Link to="/market-info" className="btn btn-success">
                      <i className="fas fa-certificate me-1"></i>Market Info
                    </Link>
                    <Link to="/education" className="btn btn-dark">
                      <i className="fas fa-graduation-cap me-1"></i>Training
                    </Link>
                  </>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SimpleDashboard;