import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import firebaseService from '../services/firebaseService.jsx';

const WoolProcessing = ({ user }) => {
  const [processingServices, setProcessingServices] = useState([]);
  const [userProcessingRequests, setUserProcessingRequests] = useState([]);
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [loading, setLoading] = useState(false);

  const [newRequest, setNewRequest] = useState({
    batchId: '',
    serviceType: 'shearing',
    description: '',
    priority: 'normal',
    estimatedWeight: '',
    specialRequirements: ''
  });

  const processingServiceTypes = [
    {
      id: 'shearing',
      name: 'Wool Shearing',
      description: 'Professional sheep shearing services',
      price: 2.50,
      duration: '1-2 days',
      icon: 'fas fa-cut'
    },
    {
      id: 'sorting',
      name: 'Wool Sorting & Grading',
      description: 'Sort wool by quality, color, and fiber length',
      price: 1.75,
      duration: '2-3 days',
      icon: 'fas fa-sort'
    },
    {
      id: 'cleaning',
      name: 'Wool Cleaning & Scouring',
      description: 'Remove dirt, grease, and impurities',
      price: 3.00,
      duration: '3-5 days',
      icon: 'fas fa-broom'
    },
    {
      id: 'dyeing',
      name: 'Wool Dyeing',
      description: 'Color wool using eco-friendly dyes',
      price: 4.50,
      duration: '5-7 days',
      icon: 'fas fa-palette'
    },
    {
      id: 'carding',
      name: 'Wool Carding',
      description: 'Prepare wool fibers for spinning',
      price: 2.25,
      duration: '2-4 days',
      icon: 'fas fa-spinner'
    },
    {
      id: 'spinning',
      name: 'Wool Spinning',
      description: 'Convert wool fibers into yarn',
      price: 5.00,
      duration: '7-10 days',
      icon: 'fas fa-circle-notch'
    }
  ];

  useEffect(() => {
    loadProcessingServices();
    loadUserRequests();
  }, [user]);

  const loadProcessingServices = async () => {
    // In a real implementation, this would load from Firebase
    setProcessingServices(processingServiceTypes);
  };

  const loadUserRequests = async () => {
    if (!user) return;
    
    try {
      // Load user's processing requests from Firebase
      const requests = await firebaseService.getUserProcessingRequests(user.uid);
      setUserProcessingRequests(requests || []);
    } catch (error) {
      console.error('Error loading processing requests:', error);
    }
  };

  const handleSubmitRequest = async () => {
    if (!newRequest.batchId || !newRequest.estimatedWeight) {
      alert('Please fill in all required fields');
      return;
    }

    setLoading(true);
    try {
      const requestData = {
        ...newRequest,
        userId: user.uid,
        farmerName: user.name || user.displayName,
        status: 'PENDING',
        createdAt: new Date(),
        estimatedCost: calculateEstimatedCost(newRequest.serviceType, newRequest.estimatedWeight)
      };

      await firebaseService.createProcessingRequest(requestData);
      
      setNewRequest({
        batchId: '',
        serviceType: 'shearing',
        description: '',
        priority: 'normal',
        estimatedWeight: '',
        specialRequirements: ''
      });
      
      setShowRequestForm(false);
      alert('Processing request submitted successfully!');
      loadUserRequests();
    } catch (error) {
      console.error('Error submitting request:', error);
      alert('Failed to submit processing request');
    }
    setLoading(false);
  };

  const calculateEstimatedCost = (serviceType, weight) => {
    const service = processingServiceTypes.find(s => s.id === serviceType);
    return service ? (service.price * parseFloat(weight)).toFixed(2) : 0;
  };

  const getStatusColor = (status) => {
    const colors = {
      'PENDING': 'warning',
      'IN_PROGRESS': 'info',
      'COMPLETED': 'success',
      'CANCELLED': 'danger'
    };
    return colors[status] || 'secondary';
  };

  return (
    <div className="container-fluid py-4">
      {/* Header */}
      <div className="row mb-4">
        <div className="col-12">
          <div className="card bg-gradient-primary text-white border-0">
            <div className="card-body">
              <div className="row align-items-center">
                <div className="col-md-8">
                  <h3 className="mb-2">
                    <i className="fas fa-cogs me-3"></i>
                    Wool Processing Services
                  </h3>
                  <p className="mb-0 opacity-75">Access professional wool processing services for your batches</p>
                </div>
                <div className="col-md-4 text-end">
                  <button 
                    className="btn btn-light btn-lg" 
                    onClick={() => setShowRequestForm(true)}
                  >
                    <i className="fas fa-plus me-2"></i>Request Service
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Processing Services */}
      <div className="row mb-4">
        <div className="col-12">
          <div className="card border-0 shadow-sm">
            <div className="card-header bg-info text-white">
              <h5 className="mb-0">
                <i className="fas fa-list me-2"></i>Available Processing Services
              </h5>
            </div>
            <div className="card-body">
              <div className="row">
                {processingServices.map(service => (
                  <div key={service.id} className="col-lg-4 col-md-6 mb-4">
                    <div className="card h-100 border-0 shadow-sm">
                      <div className="card-body text-center">
                        <div className="mb-3">
                          <i className={`${service.icon} fa-3x text-primary`}></i>
                        </div>
                        <h5 className="card-title">{service.name}</h5>
                        <p className="card-text text-muted">{service.description}</p>
                        <div className="mb-3">
                          <span className="badge bg-success fs-6">${service.price}/kg</span>
                          <span className="badge bg-info ms-2">{service.duration}</span>
                        </div>
                        <button 
                          className="btn btn-outline-primary"
                          onClick={() => {
                            setNewRequest(prev => ({ ...prev, serviceType: service.id }));
                            setShowRequestForm(true);
                          }}
                        >
                          Request Service
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* User Processing Requests */}
      <div className="row">
        <div className="col-12">
          <div className="card border-0 shadow-sm">
            <div className="card-header bg-success text-white">
              <h5 className="mb-0">
                <i className="fas fa-history me-2"></i>My Processing Requests
              </h5>
            </div>
            <div className="card-body">
              {userProcessingRequests.length === 0 ? (
                <div className="text-center py-4">
                  <i className="fas fa-inbox fa-3x text-muted mb-3"></i>
                  <h5 className="text-muted">No processing requests yet</h5>
                  <p className="text-muted">Submit your first processing request to get started</p>
                </div>
              ) : (
                <div className="table-responsive">
                  <table className="table table-hover">
                    <thead>
                      <tr>
                        <th>Request ID</th>
                        <th>Service Type</th>
                        <th>Batch ID</th>
                        <th>Weight (kg)</th>
                        <th>Estimated Cost</th>
                        <th>Status</th>
                        <th>Created</th>
                      </tr>
                    </thead>
                    <tbody>
                      {userProcessingRequests.map((request, index) => (
                        <tr key={request.id || index}>
                          <td>
                            <strong>PR-{request.id || index + 1}</strong>
                          </td>
                          <td>
                            <i className={`${processingServiceTypes.find(s => s.id === request.serviceType)?.icon} me-2`}></i>
                            {processingServiceTypes.find(s => s.id === request.serviceType)?.name}
                          </td>
                          <td>{request.batchId}</td>
                          <td>{request.estimatedWeight}</td>
                          <td>${request.estimatedCost}</td>
                          <td>
                            <span className={`badge bg-${getStatusColor(request.status)}`}>
                              {request.status}
                            </span>
                          </td>
                          <td>{new Date(request.createdAt).toLocaleDateString()}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Request Service Modal */}
      {showRequestForm && (
        <div className="modal show d-block" style={{backgroundColor: 'rgba(0,0,0,0.5)'}}>
          <div className="modal-dialog modal-lg">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Request Processing Service</h5>
                <button className="btn-close" onClick={() => setShowRequestForm(false)}></button>
              </div>
              <div className="modal-body">
                <div className="row">
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label className="form-label">Batch ID *</label>
                      <input
                        type="text"
                        className="form-control"
                        placeholder="Enter your batch ID"
                        value={newRequest.batchId}
                        onChange={(e) => setNewRequest({...newRequest, batchId: e.target.value})}
                      />
                    </div>
                    <div className="mb-3">
                      <label className="form-label">Service Type *</label>
                      <select
                        className="form-select"
                        value={newRequest.serviceType}
                        onChange={(e) => setNewRequest({...newRequest, serviceType: e.target.value})}
                      >
                        {processingServiceTypes.map(service => (
                          <option key={service.id} value={service.id}>
                            {service.name} - ${service.price}/kg
                          </option>
                        ))}
                      </select>
                    </div>
                    <div className="mb-3">
                      <label className="form-label">Estimated Weight (kg) *</label>
                      <input
                        type="number"
                        className="form-control"
                        value={newRequest.estimatedWeight}
                        onChange={(e) => setNewRequest({...newRequest, estimatedWeight: e.target.value})}
                      />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label className="form-label">Priority</label>
                      <select
                        className="form-select"
                        value={newRequest.priority}
                        onChange={(e) => setNewRequest({...newRequest, priority: e.target.value})}
                      >
                        <option value="low">Low</option>
                        <option value="normal">Normal</option>
                        <option value="high">High</option>
                        <option value="urgent">Urgent</option>
                      </select>
                    </div>
                    <div className="mb-3">
                      <label className="form-label">Special Requirements</label>
                      <textarea
                        className="form-control"
                        rows="3"
                        value={newRequest.specialRequirements}
                        onChange={(e) => setNewRequest({...newRequest, specialRequirements: e.target.value})}
                      ></textarea>
                    </div>
                    <div className="mb-3">
                      <label className="form-label">Description</label>
                      <textarea
                        className="form-control"
                        rows="3"
                        value={newRequest.description}
                        onChange={(e) => setNewRequest({...newRequest, description: e.target.value})}
                      ></textarea>
                    </div>
                  </div>
                </div>
                
                {newRequest.estimatedWeight && (
                  <div className="alert alert-info">
                    <strong>Estimated Cost:</strong> ${calculateEstimatedCost(newRequest.serviceType, newRequest.estimatedWeight)}
                  </div>
                )}
              </div>
              <div className="modal-footer">
                <button className="btn btn-secondary" onClick={() => setShowRequestForm(false)}>
                  Cancel
                </button>
                <button className="btn btn-primary" onClick={handleSubmitRequest} disabled={loading}>
                  {loading ? 'Submitting...' : 'Submit Request'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default WoolProcessing;
