import React, { useState, useEffect } from 'react';
import firebaseService from '../services/firebaseService.jsx';
import enhancedQRService from '../services/enhancedQRService.jsx';
import BatchQRScanner from '../components/BatchQRScanner.jsx';
import BatchTrackingMap from '../components/BatchTrackingMap.jsx';
import WoolQualityForm from '../components/WoolQualityForm.jsx';
import WoolQualityDetails from '../components/WoolQualityDetails.jsx';
import woolQualityService from '../services/woolQualityService.jsx';

const FarmerTraceability = ({ user }) => {
  const [myBatches, setMyBatches] = useState([]);
  const [selectedBatch, setSelectedBatch] = useState(null);
  const [trackingHistory, setTrackingHistory] = useState([]);
  const [showAddBatch, setShowAddBatch] = useState(false);
  const [showTrackingForm, setShowTrackingForm] = useState(false);
  const [showQRScanner, setShowQRScanner] = useState(false);
  const [showTrackingMap, setShowTrackingMap] = useState(false);
  const [selectedBatchForTracking, setSelectedBatchForTracking] = useState(null);
  const [loading, setLoading] = useState(false);
  const [qualityRecords, setQualityRecords] = useState([]);
  const [showQualityForm, setShowQualityForm] = useState(false);

  const [newBatch, setNewBatch] = useState({
    batchName: '',
    farmerName: user?.name || '',
    farmerId: user?.id || '',
    weight: '',
    woolType: 'Merino',
    location: '',
    coordinates: '',
    shearingDate: '',
    description: '',
    price: '',
    isListed: false
  });

  const [trackingEntry, setTrackingEntry] = useState({
    location: '',
    process: '',
    status: 'IN_TRANSIT',
    notes: '',
    coordinates: ''
  });

  useEffect(() => {
    const farmerId = user?.uid || user?.id;
    const farmerName = user?.name || user?.displayName || 'Unknown';
    
    if (farmerId && farmerName) {
      setNewBatch(prev => ({
        ...prev,
        farmerName: farmerName,
        farmerId: farmerId
      }));
      loadFarmerBatches();
    }
  }, [user?.uid, user?.id, user?.name, user?.displayName]); // eslint-disable-line react-hooks/exhaustive-deps

  const loadFarmerBatches = async () => {
    setLoading(true);
    try {
      const farmerId = user?.uid;
      if (!farmerId) {
        setLoading(false);
        return;
      }
      
      const batches = await firebaseService.getFarmerBatches(farmerId);
      setMyBatches(batches || []);
    } catch (error) {
      console.error('Error loading batches:', error);
      setMyBatches([]);
    }
    setLoading(false);
  };

  const handleCreateBatch = async () => {
    if (!newBatch.batchName || !newBatch.weight || !newBatch.location) {
      alert('Please fill in all required fields');
      return;
    }

    setLoading(true);
    try {
      const batchData = {
        batchName: newBatch.batchName,
        farmerName: user?.name || user?.displayName || 'Unknown',
        farmerId: user?.uid,
        weight: parseFloat(newBatch.weight),
        woolType: newBatch.woolType,
        location: newBatch.location,
        coordinates: newBatch.coordinates || '0,0',
        shearingDate: newBatch.shearingDate,
        description: newBatch.description,
        price: parseFloat(newBatch.price) || 0,
        isListed: newBatch.isListed
      };

      const batch = await firebaseService.createBatch(batchData);
      
      // Generate QR code for the batch
      try {
        const qrResult = await enhancedQRService.generateBatchQR({
          batchId: batch.batchId,
          farmerId: user?.uid,
          farmerName: user?.name || user?.displayName || 'Unknown',
          weight: parseFloat(newBatch.weight),
          createdAt: new Date().toISOString()
        });
        
        // Update batch with QR code
        await firebaseService.updateBatch(batch.batchId, {
          qrCode: qrResult.qrCode,
          qrData: qrResult.qrData
        });
        
        console.log('QR code generated for batch:', batch.batchId);
      } catch (qrError) {
        console.warn('QR code generation failed:', qrError);
        // Continue without QR code
      }
      
      setNewBatch({
        batchName: '',
        farmerName: user?.name || '',
        farmerId: user?.uid || '',
        weight: '',
        woolType: 'Merino',
        location: '',
        coordinates: '',
        shearingDate: '',
        description: '',
        price: '',
        isListed: false
      });
      
      setShowAddBatch(false);
      alert('Batch created successfully!');
      loadFarmerBatches();
    } catch (error) {
      console.error('Error creating batch:', error);
      alert('Error: ' + error.message);
    }
    setLoading(false);
  };

  const handleSelectBatch = async (batch) => {
    setSelectedBatch(batch);
    
    try {
      const history = await firebaseService.getTrackingHistory(batch.batchId);
      setTrackingHistory(history);
      await loadQualityRecords(batch.batchId);
    } catch (error) {
      console.error('Error loading tracking history or quality:', error);
    }
  };

  const handleQRScanSuccess = (trackingEntry) => {
    // Reload tracking history for the scanned batch
    if (trackingEntry.batchId) {
      loadTrackingHistory(trackingEntry.batchId);
    }
    // Reload batches to update status
    loadFarmerBatches();
  };

  const handleViewTrackingMap = (batchId) => {
    setSelectedBatchForTracking(batchId);
    setShowTrackingMap(true);
  };

  const loadTrackingHistory = async (batchId) => {
    try {
      const history = await firebaseService.getBatchTrackingHistory(batchId);
      setTrackingHistory(history);
    } catch (error) {
      console.error('Error loading tracking history:', error);
      setTrackingHistory([]);
    }
  };

  const handleAddTracking = async () => {
    if (!selectedBatch || !trackingEntry.location) {
      alert('Please select a batch and enter location');
      return;
    }

    setLoading(true);
    try {
      await firebaseService.addTrackingEntry(selectedBatch.batchId, {
        ...trackingEntry,
        actor: user?.name || 'Unknown',
        coordinates: trackingEntry.coordinates.split(',').map(coord => parseFloat(coord.trim()))
      });

      const history = await firebaseService.getTrackingHistory(selectedBatch.batchId);
      setTrackingHistory(history);

      // Reset form
      setTrackingEntry({
        location: '',
        process: '',
        status: 'IN_TRANSIT',
        notes: '',
        coordinates: ''
      });
      
      setShowTrackingForm(false);
      alert('Tracking entry added successfully!');
    } catch (error) {
      console.error('Error adding tracking:', error);
      alert('Failed to add tracking entry');
    }
    setLoading(false);
  };

  const handleQRScan = async () => {
    try {
      const scanResult = await enhancedQRService.simulateQRScan();
      
      if (scanResult.success) {
        const validation = await enhancedQRService.validateQRCode(scanResult.data, firebaseService);
        
        if (validation.isValid) {
          setSelectedBatch(validation.batch);
          const history = await firebaseService.getTrackingHistory(validation.batch.batchId);
          setTrackingHistory(history);
          setShowQRScanner(false);
          alert(`QR Code scanned successfully! Loaded batch: ${validation.batch.batchId}`);
        } else {
          alert(`Invalid QR Code: ${validation.error}`);
        }
      }
    } catch (error) {
      console.error('QR scan error:', error);
      alert('Failed to scan QR code');
    }
  };

  const downloadQRCode = (batch) => {
    if (batch.qrCode) {
      enhancedQRService.downloadQRCode(batch.qrCode, `batch-${batch.batchId}-qr.png`);
    }
  };

  const printQRCode = (batch) => {
    if (batch.qrCode) {
      enhancedQRService.printQRCode(batch.qrCode, batch);
    }
  };

  const getStatusColor = (status) => {
    const colors = {
      'REGISTERED': 'primary',
      'IN_TRANSIT': 'warning',
      'PROCESSING': 'info',
      'QUALITY_VERIFIED': 'success',
      'SOLD': 'success',
      'QUALITY_REJECTED': 'danger',
      'PENDING_QUALITY_CHECK': 'secondary'
    };
    return colors[status] || 'secondary';
  };

  const loadQualityRecords = async (batchId) => {
    try {
      const records = await woolQualityService.getQualityRecordByBatch(batchId);
      setQualityRecords(records);
    } catch (err) {
      setQualityRecords([]);
    }
  };

  return (
    <div className="container-fluid py-4">
      {/* Header */}
      <div className="row mb-4">
        <div className="col-12">
          <div className="card bg-gradient-success text-white border-0">
            <div className="card-body">
              <div className="row align-items-center">
                <div className="col-md-8">
                  <h3 className="mb-2">
                    <i className="fas fa-seedling me-3"></i>
                    Farmer Traceability Dashboard
                  </h3>
                  <p className="mb-0 opacity-75">Manage your wool batches with blockchain tracking and QR codes</p>
                </div>
                <div className="col-md-4 text-end">
                  <button className="btn btn-light btn-lg me-2" onClick={() => setShowAddBatch(true)}>
                    <i className="fas fa-plus me-2"></i>Add Batch
                  </button>
                  <button className="btn btn-outline-light btn-lg" onClick={() => setShowQRScanner(true)}>
                    <i className="fas fa-qrcode me-2"></i>Scan QR
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="row mb-4">
        <div className="col-md-3">
          <div className="card bg-primary text-white">
            <div className="card-body text-center">
              <i className="fas fa-boxes fa-2x mb-2"></i>
              <h4>{myBatches.length}</h4>
              <small>Total Batches</small>
            </div>
          </div>
        </div>
        <div className="col-md-3">
          <div className="card bg-info text-white">
            <div className="card-body text-center">
              <i className="fas fa-truck fa-2x mb-2"></i>
              <h4>{myBatches.filter(b => b.status === 'IN_TRANSIT').length}</h4>
              <small>In Transit</small>
            </div>
          </div>
        </div>
        <div className="col-md-3">
          <div className="card bg-warning text-white">
            <div className="card-body text-center">
              <i className="fas fa-certificate fa-2x mb-2"></i>
              <h4>{myBatches.filter(b => b.status === 'QUALITY_VERIFIED').length}</h4>
              <small>Quality Verified</small>
            </div>
          </div>
        </div>
        <div className="col-md-3">
          <div className="card bg-success text-white">
            <div className="card-body text-center">
              <i className="fas fa-dollar-sign fa-2x mb-2"></i>
              <h4>{myBatches.filter(b => b.status === 'SOLD').length}</h4>
              <small>Sold</small>
            </div>
          </div>
        </div>
      </div>

      <div className="row">
        {/* My Batches */}
        <div className="col-lg-8">
          <div className="card border-0 shadow-sm">
            <div className="card-header bg-primary text-white">
              <h5 className="mb-0">
                <i className="fas fa-list me-2"></i>My Wool Batches
              </h5>
            </div>
            <div className="card-body">
              {loading ? (
                <div className="text-center py-4">
                  <div className="spinner-border text-primary"></div>
                  <p className="mt-2">Loading batches...</p>
                </div>
              ) : myBatches.length === 0 ? (
                <div className="text-center py-4">
                  <i className="fas fa-inbox fa-3x text-muted mb-3"></i>
                  <h5 className="text-muted">No batches yet</h5>
                  <p className="text-muted">Create your first wool batch to get started</p>
                </div>
              ) : (
                <div className="table-responsive">
                  <table className="table table-hover">
                    <thead>
                      <tr>
                        <th>Batch ID</th>
                        <th>Weight (kg)</th>
                        <th>Location</th>
                        <th>Status</th>
                        <th>Created</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {myBatches.map((batch, index) => (
                        <tr key={`${batch.batchId}-${batch.id || index}`} className={selectedBatch?.batchId === batch.batchId ? 'table-active' : ''}>
                          <td>
                            <strong>{batch.batchId}</strong>
                            {batch.qrCode && <i className="fas fa-qrcode text-success ms-2"></i>}
                          </td>
                          <td>{batch.weight}</td>
                          <td>
                            {typeof (batch.currentLocation || batch.location) === 'object' && (batch.currentLocation || batch.location) !== null && 'lat' in (batch.currentLocation || batch.location) && 'lng' in (batch.currentLocation || batch.location)
                              ? `${(batch.currentLocation || batch.location).lat}, ${(batch.currentLocation || batch.location).lng}`
                              : batch.currentLocation || batch.location || 'Unknown'}
                          </td>
                          <td>
                            <span className={`badge bg-${getStatusColor(batch.status)}`}>
                              {batch.status}
                            </span>
                          </td>
                          <td>{new Date(batch.createdAt).toLocaleDateString()}</td>
                          <td>
                            <div className="btn-group btn-group-sm">
                              <button
                                className="btn btn-outline-primary"
                                onClick={() => handleSelectBatch(batch)}
                                title="View Details"
                              >
                                <i className="fas fa-eye"></i>
                              </button>
                              <button
                                className="btn btn-outline-success"
                                onClick={() => handleViewTrackingMap(batch.batchId)}
                                title="View Tracking Map"
                              >
                                <i className="fas fa-map-marked-alt"></i>
                              </button>
                              <button
                                className="btn btn-outline-info"
                                onClick={() => {
                                  setSelectedBatchForTracking(batch.batchId);
                                  setShowQRScanner(true);
                                }}
                                title="Scan QR Code"
                              >
                                <i className="fas fa-qrcode"></i>
                              </button>
                              {batch.qrCode && (
                                <>
                                  <button
                                    className="btn btn-outline-warning"
                                    onClick={() => downloadQRCode(batch)}
                                    title="Download QR Code"
                                  >
                                    <i className="fas fa-download"></i>
                                  </button>
                                  <button
                                    className="btn btn-outline-secondary"
                                    onClick={() => printQRCode(batch)}
                                    title="Print QR Code"
                                  >
                                    <i className="fas fa-print"></i>
                                  </button>
                                </>
                              )}
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Batch Details & Tracking */}
        <div className="col-lg-4">
          {selectedBatch ? (
            <div className="card border-0 shadow-sm">
              <div className="card-header bg-info text-white d-flex justify-content-between align-items-center">
                <h6 className="mb-0">Batch Details</h6>
                <button
                  className="btn btn-light btn-sm"
                  onClick={() => setShowTrackingForm(true)}
                >
                  <i className="fas fa-plus me-1"></i>Add Tracking
                </button>
              </div>
              <div className="card-body">
                <div className="mb-3">
                  <strong>Batch ID:</strong> {selectedBatch.batchId}
                </div>
                <div className="mb-3">
                  <strong>Weight:</strong> {selectedBatch.weight} kg
                </div>
                <div className="mb-3">
                  <strong>Status:</strong>
                  <span className={`badge bg-${getStatusColor(selectedBatch.status)} ms-2`}>
                    {selectedBatch.status}
                  </span>
                </div>
                <div className="mb-3">
                  <strong>Current Location:</strong> {
                    typeof (selectedBatch.currentLocation || selectedBatch.location) === 'object' && (selectedBatch.currentLocation || selectedBatch.location) !== null && 'lat' in (selectedBatch.currentLocation || selectedBatch.location) && 'lng' in (selectedBatch.currentLocation || selectedBatch.location)
                      ? `${(selectedBatch.currentLocation || selectedBatch.location).lat}, ${(selectedBatch.currentLocation || selectedBatch.location).lng}`
                      : selectedBatch.currentLocation || selectedBatch.location || 'Unknown'
                  }
                </div>

                {selectedBatch.qrCode && (
                  <div className="text-center mb-3">
                    <img src={selectedBatch.qrCode} alt="Batch QR Code" className="img-fluid" style={{maxWidth: '150px'}} />
                  </div>
                )}

                <h6 className="mt-4 mb-3">Tracking History</h6>
                {trackingHistory.length === 0 ? (
                  <p className="text-muted small">No tracking entries yet</p>
                ) : (
                  <div className="timeline-sm">
                    {trackingHistory.map((entry, index) => (
                      <div key={`${entry.entryId || entry.timestamp}-${index}`} className="timeline-item-sm">
                        <div className="timeline-marker-sm">
                          <i className="fas fa-map-marker-alt"></i>
                        </div>
                        <div className="timeline-content-sm">
                          <div className="fw-bold small">{
                            typeof entry.location === 'object' && entry.location !== null && 'lat' in entry.location && 'lng' in entry.location
                              ? `${entry.location.lat}, ${entry.location.lng}`
                              : entry.location || 'Unknown'
                          }</div>
                          <div className="text-muted small">{entry.process}</div>
                          <div className="text-muted" style={{fontSize: '0.75rem'}}>
                            {new Date(entry.timestamp).toLocaleString()}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
              {qualityRecords.length > 0 ? (
                <WoolQualityDetails quality={qualityRecords[0]} />
              ) : (
                <div className="mb-2"><em>No wool quality record yet.</em></div>
              )}
              {selectedBatch.status === 'QUALITY_REJECTED' && (
                <div className="alert alert-danger my-2">
                  <h6 className="mb-1">Rejected for quality:</h6>
                  <div>{selectedBatch.rejectionReason || 'No reason specified.'}</div>
                </div>
              )}
              {(user?.role === 'Farmer' || user?.role === 'Inspector') && selectedBatch &&
                (selectedBatch.status === 'PENDING_QUALITY_CHECK' || selectedBatch.status === 'QUALITY_REJECTED') && (
                  <button className="btn btn-outline-success w-100 mb-2" onClick={() => setShowQualityForm(true)}>
                    {qualityRecords.length > 0 ? 'Resubmit Wool Quality' : 'Add Wool Quality'}
                  </button>
                )
              }
              {showQualityForm && (
                <div className="modal show d-block" style={{backgroundColor:'rgba(0,0,0,0.35)'}}>
                  <div className="modal-dialog">
                    <div className="modal-content">
                      <div className="modal-header">
                        <h5 className="modal-title">{qualityRecords.length > 0 ? 'Edit Quality Record' : 'Add Quality Record'}</h5>
                        <button className="btn-close" onClick={()=>setShowQualityForm(false)}></button>
                      </div>
                      <div className="modal-body">
                        <WoolQualityForm batchId={selectedBatch.batchId} onSave={() => {loadQualityRecords(selectedBatch.batchId);setShowQualityForm(false);}} />
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="card border-0 shadow-sm">
              <div className="card-body text-center py-5">
                <i className="fas fa-mouse-pointer fa-3x text-muted mb-3"></i>
                <h6 className="text-muted">Select a batch to view details</h6>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Add Batch Modal */}
      {showAddBatch && (
        <div className="modal show d-block" style={{backgroundColor: 'rgba(0,0,0,0.5)'}}>
          <div className="modal-dialog modal-lg">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Add New Wool Batch</h5>
                <button className="btn-close" onClick={() => setShowAddBatch(false)}></button>
              </div>
              <div className="modal-body">
                <div className="row">
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label className="form-label">Batch Name *</label>
                      <input
                        type="text"
                        className="form-control"
                        placeholder="e.g., Premium Merino Batch 2024"
                        value={newBatch.batchName}
                        onChange={(e) => setNewBatch({...newBatch, batchName: e.target.value})}
                      />
                    </div>
                    <div className="mb-3">
                      <label className="form-label">Weight (kg) *</label>
                      <input
                        type="number"
                        className="form-control"
                        value={newBatch.weight}
                        onChange={(e) => setNewBatch({...newBatch, weight: e.target.value})}
                      />
                    </div>
                    <div className="mb-3">
                      <label className="form-label">Wool Type</label>
                      <select
                        className="form-select"
                        value={newBatch.woolType}
                        onChange={(e) => setNewBatch({...newBatch, woolType: e.target.value})}
                      >
                        <option value="Merino">Merino</option>
                        <option value="Romney">Romney</option>
                        <option value="Corriedale">Corriedale</option>
                        <option value="Leicester">Leicester</option>
                      </select>
                    </div>
                    <div className="mb-3">
                      <label className="form-label">Farm Location *</label>
                      <input
                        type="text"
                        className="form-control"
                        value={newBatch.location}
                        onChange={(e) => setNewBatch({...newBatch, location: e.target.value})}
                      />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label className="form-label">Coordinates (lat, lng)</label>
                      <div className="input-group">
                        <input
                          type="text"
                          className="form-control"
                          placeholder="e.g., -33.8688, 151.2093"
                          value={newBatch.coordinates}
                          onChange={(e) => setNewBatch({...newBatch, coordinates: e.target.value})}
                        />
                        <button 
                          className="btn btn-outline-primary"
                          type="button"
                          onClick={() => {
                            if (navigator.geolocation) {
                              navigator.geolocation.getCurrentPosition(
                                (position) => {
                                  const coords = `${position.coords.latitude}, ${position.coords.longitude}`;
                                  setNewBatch({...newBatch, coordinates: coords});
                                },
                                (error) => alert('Unable to get location: ' + error.message)
                              );
                            } else {
                              alert('Geolocation is not supported by this browser.');
                            }
                          }}
                        >
                          <i className="fas fa-map-marker-alt"></i>
                        </button>
                      </div>
                    </div>
                    <div className="mb-3">
                      <label className="form-label">Shearing Date</label>
                      <input
                        type="date"
                        className="form-control"
                        value={newBatch.shearingDate}
                        onChange={(e) => setNewBatch({...newBatch, shearingDate: e.target.value})}
                      />
                    </div>
                    <div className="mb-3">
                      <label className="form-label">Price per kg ($)</label>
                      <input
                        type="number"
                        step="0.01"
                        className="form-control"
                        value={newBatch.price}
                        onChange={(e) => setNewBatch({...newBatch, price: e.target.value})}
                      />
                    </div>
                  </div>
                </div>
                <div className="mb-3">
                  <label className="form-label">Description</label>
                  <textarea
                    className="form-control"
                    rows="3"
                    value={newBatch.description}
                    onChange={(e) => setNewBatch({...newBatch, description: e.target.value})}
                  ></textarea>
                </div>
                <div className="form-check">
                  <input
                    className="form-check-input"
                    type="checkbox"
                    checked={newBatch.isListed}
                    onChange={(e) => setNewBatch({...newBatch, isListed: e.target.checked})}
                  />
                  <label className="form-check-label">List in marketplace</label>
                </div>
              </div>
              <div className="modal-footer">
                <button className="btn btn-secondary" onClick={() => setShowAddBatch(false)}>
                  Cancel
                </button>
                <button className="btn btn-success" onClick={handleCreateBatch} disabled={loading}>
                  {loading ? 'Creating...' : 'Create Batch'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Add Tracking Modal */}
      {showTrackingForm && (
        <div className="modal show d-block" style={{backgroundColor: 'rgba(0,0,0,0.5)'}}>
          <div className="modal-dialog">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Add Tracking Entry</h5>
                <button className="btn-close" onClick={() => setShowTrackingForm(false)}></button>
              </div>
              <div className="modal-body">
                <div className="mb-3">
                  <label className="form-label">Location *</label>
                  <input
                    type="text"
                    className="form-control"
                    value={trackingEntry.location}
                    onChange={(e) => setTrackingEntry({...trackingEntry, location: e.target.value})}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Process/Activity</label>
                  <select
                    className="form-select"
                    value={trackingEntry.process}
                    onChange={(e) => setTrackingEntry({...trackingEntry, process: e.target.value})}
                  >
                    <option value="">Select process...</option>
                    <option value="Transport">Transport</option>
                    <option value="Storage">Storage</option>
                    <option value="Processing">Processing</option>
                    <option value="Quality Check">Quality Check</option>
                    <option value="Packaging">Packaging</option>
                  </select>
                </div>
                <div className="mb-3">
                  <label className="form-label">Status</label>
                  <select
                    className="form-select"
                    value={trackingEntry.status}
                    onChange={(e) => setTrackingEntry({...trackingEntry, status: e.target.value})}
                  >
                    <option value="IN_TRANSIT">In Transit</option>
                    <option value="PROCESSING">Processing</option>
                    <option value="STORED">Stored</option>
                    <option value="QUALITY_CHECK">Quality Check</option>
                  </select>
                </div>
                <div className="mb-3">
                  <label className="form-label">Coordinates (lat, lng)</label>
                  <input
                    type="text"
                    className="form-control"
                    placeholder="e.g., -33.8688, 151.2093"
                    value={trackingEntry.coordinates}
                    onChange={(e) => setTrackingEntry({...trackingEntry, coordinates: e.target.value})}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Notes</label>
                  <textarea
                    className="form-control"
                    rows="3"
                    value={trackingEntry.notes}
                    onChange={(e) => setTrackingEntry({...trackingEntry, notes: e.target.value})}
                  ></textarea>
                </div>
              </div>
              <div className="modal-footer">
                <button className="btn btn-secondary" onClick={() => setShowTrackingForm(false)}>
                  Cancel
                </button>
                <button className="btn btn-primary" onClick={handleAddTracking} disabled={loading}>
                  {loading ? 'Adding...' : 'Add Entry'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Enhanced QR Scanner Modal */}
      {showQRScanner && (
        <BatchQRScanner
          onScanSuccess={handleQRScanSuccess}
          onClose={() => setShowQRScanner(false)}
          user={user}
        />
      )}

      {/* Batch Tracking Map Modal */}
      {showTrackingMap && selectedBatchForTracking && (
        <BatchTrackingMap
          batchId={selectedBatchForTracking}
          onClose={() => {
            setShowTrackingMap(false);
            setSelectedBatchForTracking(null);
          }}
        />
      )}

      <style>{`
        .timeline-sm {
          position: relative;
          padding-left: 20px;
        }
        
        .timeline-sm::before {
          content: '';
          position: absolute;
          left: 8px;
          top: 0;
          bottom: 0;
          width: 2px;
          background: #dee2e6;
        }
        
        .timeline-item-sm {
          position: relative;
          margin-bottom: 15px;
        }
        
        .timeline-marker-sm {
          position: absolute;
          left: -16px;
          top: 2px;
          width: 16px;
          height: 16px;
          border-radius: 50%;
          background: #007bff;
          color: white;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 8px;
        }
        
        .timeline-content-sm {
          margin-left: 10px;
        }
      `}</style>
    </div>
  );
};

export default FarmerTraceability;